    function companionIncompleteError(report) {
        const names=(report?.missing||[]).map(item=>`${item.label}${item.actual}/${item.min}`).join('、')||'Mục chưa rõ';
        const error=new Error(`Bảy điều hậu trường trả về JSON hợp lệ nhưng chưa đầy đủ: ${names}`);
        error.name='CompanionPayloadIncompleteError';
        error.completenessReport=report;
        return error;
    }

    async function repairIncompleteCompanionTask(task, { floor, signature, message } = {}) {
        const primaryRaw=parseGeneratedJson(task?.result?.text||'{}');
        const primaryPayload=normalizeCompanionPayload(primaryRaw,Number(floor),String(signature||''));
        const before=companionCompletenessReport(primaryPayload,floor,message);
        const diagnostics={attempted:false,status:'not-needed',before:before.counts,after:before.counts,missingBefore:before.missing,missingAfter:[]};
        if(!before.missing.length){task.completenessRepair=diagnostics;return task;}
        diagnostics.attempted=true;diagnostics.status='running';
        updateCompanionFallbackProgress(Number(floor),93,'Một số mục của Bảy điều hậu trường đang trống, đang bổ sung qua API riêng',before.missing.map(item=>item.label).join(', '));
        const scope=captureChatScope();const generation=stateRuntime.dataGeneration;const stateAtStart=stateRuntime.state;
        const configured=Math.max(1800,Math.min(5000,Number(stateRuntime.serverConfig?.companion?.maxTokens||5000)));
        const repairPrompt=companionRepairPrompt(before,primaryPayload,message);
        const repairOptions={
            responseLength:configured,
            systemPrompt:`${FALLEN_WRITER_CONTEXT}\n\nBạn chỉ có nhiệm vụ bù đủ những mục đời sống còn thiếu trong bản JSON trước của Bảy điều hậu trường, không viết lại chính văn và phần trên đã hoàn thành.`,
            jsonMode:true,
            generationType:'companion-scoped',
            finalInstruction:COMPANION_REPAIR_FINAL_CONTRACT,
            progressFloor:Number(floor),
        };
        let repairData;
        try {
            repairData=await callCompanionJsonWithRecovery(repairPrompt,repairOptions);
        } catch (error) {
            throw error;
        }
        if(!chatScopeIsCurrent(scope)||stateRuntime.dataGeneration!==generation||stateRuntime.state!==stateAtStart)throw new Error('Đã đổi cuộc trò chuyện: đã loại bỏ kết quả bổ sung mục thiếu của Bảy điều hậu trường');
        const repairRaw=parseGeneratedJson(repairData?.text||'{}');
        const combinedRaw=mergeCompanionRepairRaw(primaryRaw,repairRaw,before);
        const combinedPayload=normalizeCompanionPayload(combinedRaw,Number(floor),String(signature||''));
        const after=companionCompletenessReport(combinedPayload,floor,message);
        diagnostics.status=after.missing.length?'incomplete':'ok';diagnostics.after=after.counts;diagnostics.missingAfter=after.missing;
        diagnostics.model=compactText(repairData?.model||'',160);diagnostics.provider=compactText(repairData?.provider||'',100);
        if(after.missing.length)throw companionIncompleteError(after);
        task.result={...(task.result||{}),text:JSON.stringify(combinedRaw)};
        task.completenessRepair=diagnostics;
        return task;
    }

    function mergeMomentReactionPatch(reaction, payload) {
        const moment = phoneMomentById(reaction?.momentId);
        if (!moment) return false;
        const priorSeen=new Set((moment.seenBy||[]).map(name=>npcNameKey(name)));
        moment._reactionHistory=Array.isArray(moment._reactionHistory)?moment._reactionHistory:[];
        if(!moment._reactionHistory.some(item=>item?._sidecarId===payload?.id))moment._reactionHistory.push({
            _sidecarId:payload?.id||'',seenBy:clone(moment.seenBy||[]),likes:clone(moment.likes||[]),comments:clone(moment.comments||[]),
            reactionStatus:moment.reactionStatus||'',reactionProcessedAt:moment.reactionProcessedAt||'',reactionFloor:moment.reactionFloor,
        });
        moment.seenBy = [...new Set([...(moment.seenBy||[]), ...(reaction.seenBy||[]), ...(reaction.likes||[]), ...(reaction.comments||[]).map(item=>item.author)].map(name=>relationPartyName(name)).filter(Boolean))].slice(0,120);
        for(const npc of moment.seenBy)if(!priorSeen.has(npcNameKey(npc)))s12RecordKnowledge({eventId:moment.id,relatedId:moment.id,subject:'Bài đăng Khoảnh khắc',summary:`${moment.content||'[không có chữ]'}${phoneAttachmentSummary(moment.attachments)?` · tệp đính kèm: ${phoneAttachmentSummary(moment.attachments)}`:''}`,npc,method:'moment',channel:'Khoảnh khắc',floor:payload?.floor??-1,source:'moment'});
        moment.likes = [...new Set([...(moment.likes||[]), ...(reaction.likes||[])].map(name=>relationPartyName(name)).filter(Boolean))].slice(0,80);
        moment.comments = Array.isArray(moment.comments) ? moment.comments : [];
        const seen = new Set(moment.comments.map(item=>`${npcNameKey(item?.author)}|${compactText(item?.content,500)}`));
        for (const comment of reaction.comments || []) {
            const key=`${npcNameKey(comment?.author)}|${compactText(comment?.content,500)}`;
            if(!comment?.author||!comment?.content||seen.has(key))continue;
            seen.add(key);moment.comments.push({...comment,_sidecarId:payload?.id||'',_floor:payload?.floor});
        }
        if(reaction.processed!==false){
            moment.reactionStatus='processed';
            moment.reactionProcessedAt=payload?.generatedAt||nowText();
            moment.reactionFloor=Number(payload?.floor);
        }
        return true;
    }

    function rollbackMomentReactionPayload(payloadId) {
        for(const moment of stateRuntime.state?.storyExtras?.moments||[]){
            const history=Array.isArray(moment?._reactionHistory)?moment._reactionHistory:[];
            const index=history.map(item=>item?._sidecarId).lastIndexOf(payloadId);
            if(index<0)continue;
            const snapshot=history[index];history.splice(index,1);
            moment.seenBy=clone(snapshot.seenBy||[]);moment.likes=clone(snapshot.likes||[]);moment.comments=clone(snapshot.comments||[]);
            moment.reactionStatus=snapshot.reactionStatus||'pending';moment.reactionProcessedAt=snapshot.reactionProcessedAt||'';
            if(snapshot.reactionFloor===undefined)delete moment.reactionFloor;else moment.reactionFloor=snapshot.reactionFloor;
            moment._reactionHistory=history;
        }
    }

    function mergeCompanionPayload(payload) {
        const s = stateRuntime.state;
        const userName = compactText(context()?.name1 || '{{user}}', 80) || '{{user}}';
        const payloadCreatedAt=Number.isFinite(Date.parse(String(payload?.generatedAt||'')))?Date.parse(String(payload.generatedAt)):Date.now();
        // P29: hàng rào hiện thực thứ hai. Kể cả khi sidecar từ cache cũ/nhập tay đi vòng qua normalize,
        // vẫn tuyệt đối không cho Bảy điều hậu trường ghi đè trực tiếp lên thời gian/địa điểm/thế giới/thời đại.
        const guarded = sanitizeCompanionReality(payload.setting || {}, payload.scene || {});
        payload.setting = guarded.setting;
        payload.scene = guarded.scene;
        payload.realityAudit = [...new Set([...(payload.realityAudit||[]),...(guarded.audit||[])])];
        if (payload.setting) s.communicationProfile = { ...s.communicationProfile, ...payload.setting, updatedAt: payload.generatedAt || nowText() };
        if (payload.scene) for (const [key,value] of Object.entries(payload.scene)) if (String(value || '').trim()) s.scene[key] = value;
        const s39VisibleNarrative=messageText(context()?.chat?.[Number(payload?.floor)]||{}),s39Present=s39RefreshOfflineAcquaintance(s39VisibleNarrative, Number(payload?.floor));
        if(s39VisibleNarrative)s39RecordStoryEvent({type:'narrative',relatedId:`assistant-floor:${Number(payload?.floor)}`,participants:[compactText(context()?.name1||'{{user}}',80)||'{{user}}',...s39Present],knownBy:[compactText(context()?.name1||'{{user}}',80)||'{{user}}',...s39Present],userKnows:true,channel:'Hiện thực chính văn',status:'Đã xảy ra',summary:compactText(sanitizeRetrievalDocumentText(s39VisibleNarrative),900),floor:Number(payload?.floor),time:compactText(s.scene?.time||'',120),location:compactText(s.scene?.location||'',180),source:'main-narrative'});
        updateWorldTransit(s.communicationProfile, Number(payload.floor));
        if (payload.realityAudit?.length) {
            console.warn('[0-32·P29] Đã chặn Bảy điều hậu trường sửa hiện thực', payload.realityAudit);
            const severe=payload.realityAudit.find(item=>/năm|địa điểm/i.test(item));
            if(severe) toast(`🛡 Khóa hiện thực hiện tại: ${severe}`, 'warning');
        }

        // Lời hẹn/bí mật thuộc loại “thực thể trạng thái hiện tại”, dùng khóa thực thể ổn định để ghi đè cập nhật; trạng thái cũ vào _history, cấm cứ mỗi lượt đổi chữ lại thêm một dòng mới.
        const payloadMessageKey=messageStableKey(context()?.chat?.[Number(payload.floor)]);
        for (const item of payload.promises || []) upsertPromiseSnapshot(item, Number(payload.floor), payloadMessageKey, {_sidecarId:payload.id});
        for (const item of payload.secrets || []) upsertSecretSnapshot(item, Number(payload.floor), payloadMessageKey, {_sidecarId:payload.id});
        compactCurrentStateCollections(s);
        reconcilePromiseLifecycleForState(s, Math.max(Number(payload.floor), (context()?.chat?.length || 1) - 1));

        // P41-S1: Bảy điều hậu trường không ghi core memory nữa, tránh để cùng một lượt trả lời của AI bị ghi hai lần bởi “API bảy điều + luồng ký ức chính”.
        // Bảy điều vẫn giữ liên lạc/Bỉ Gian Tư Văn/lời hẹn và bí mật ở tầng trên/ngoại hình nhân vật.
        for (const item of payload.appearances || []) upsertAppearanceSnapshot(item, payload.id, payload.floor);

        s.storyExtras ||= { moments:[], diary:[], anniversaries:[] };
        for (const reaction of payload.story?.reactions || []) mergeMomentReactionPatch(reaction,payload);
        for (const key of ['moments','diary','anniversaries']) {
            for (const item of payload.story?.[key] || []) {
                const stored={ ...item, _sidecarId:payload.id, _floor:payload.floor };s.storyExtras[key].push(stored);
                const author=relationPartyName(item?.author),userName=compactText(context()?.name1||'{{user}}',80)||'{{user}}';
                if(key==='diary'&&author)s39RecordStoryEvent({type:'private-diary',relatedId:stored.id||`${payload.id}:diary:${author}`,participants:[author],knownBy:[author],userKnows:npcNameKey(author)===npcNameKey(userName),channel:'Nhật ký riêng',status:'Đã viết',summary:`Nhật ký của ${author}: ${compactText(item?.content,700)}`,floor:payload.floor,time:item?.time,source:'companion-diary'});
                if(key==='moments'&&author)s39RecordStoryEvent({type:'moment',relatedId:stored.id||`${payload.id}:moment:${author}`,participants:[author],knownBy:[author,...(item?.seenBy||[])],userKnows:Boolean((item?.seenBy||[]).some(name=>npcNameKey(name)===npcNameKey(userName))),channel:'Khoảnh khắc',status:'Đã đăng',summary:`${author}：${compactText(item?.content,700)}`,floor:payload.floor,time:item?.time,source:'companion-moment'});
            }
        }

        s.phone.groupProfiles ||= [];
        for (const profile of payload.phone?.groupProfiles || []) {
            const name = compactText(profile?.groupName,120);
            if (!name) continue;
            for (const member of profile.members || []) registerNpcIdentity({name:member, source:`wechat-group:${name}`, floor:payload.floor}, payload.floor);
            const scope=profile.scope||'local'; const homeKey=profile.homeWorldKey||(scope==='origin'?(s.worldTransit?.origin?.worldKey||'origin-modern'):(payload.setting?.worldKey||''));
            let existing = s.phone.groupProfiles.find(row => compactText(row?.groupName,120) === name && compactText(row?.homeWorldKey,120)===compactText(homeKey,120));
            const mergedMembers = [...new Set([...(existing?.members||[]), ...(profile.members||[])].map(x=>compactText(x,80)).filter(Boolean))].slice(0,50);
            if (!existing) {
                existing = { id:uid('group-profile'), groupName:name, type:profile.type||'other', members:mergedMembers, topic:profile.topic||'', activityLevel:profile.activityLevel||'medium', source:profile.source||'', scope, homeWorldKey:homeKey, channelType:profile.channelType||(payload.setting?.communicationType==='smartphone'?'wechat':payload.setting?.communicationType||'terminal'), availability:profile.availability||(scope==='origin'?(payload.setting?.originReachable?'active':'offline-origin'):'active'), createdAt:Date.now(), updatedAt:Date.now(), _floor:payload.floor };
                s.phone.groupProfiles.push(existing);
            } else {
                existing.members = mergedMembers;
                if (profile.type && profile.type !== 'other') existing.type = profile.type;
                if (profile.topic) existing.topic = profile.topic;
                if (profile.activityLevel) existing.activityLevel = profile.activityLevel;
                if (profile.source) existing.source = profile.source;
                if (profile.scope) existing.scope = profile.scope;
                if (profile.homeWorldKey) existing.homeWorldKey = profile.homeWorldKey;
                if (profile.channelType) existing.channelType = normalizeGroupChannelType(profile.channelType, existing.channelType || 'wechat');
                if (profile.availability) existing.availability = profile.availability;
                existing.updatedAt = Date.now(); existing._floor = payload.floor;
            }
            ensurePhoneGroupThread(name, mergedMembers, homeKey);
        }

        if (payload.phone.write) {
            for (const key of ['wechat','sms','calls']) {
                s.phone[key] ||= [];
                for (const rawItem of payload.phone[key] || []) {
                    const item = { ...rawItem, author:canonicalNpcName(rawItem.author)||rawItem.author, contact:canonicalNpcName(rawItem.contact)||rawItem.contact };
                    if(key==='calls')s12ApplyCallReceipt(item);
                    if (key === 'wechat') {
                        const other=compactText((item.author===userName||item.author==='{{user}}')?item.contact:item.author,80);
                        const cp=phoneContactProfile(other);
                        if (cp?.scope==='origin' && !payload.setting?.originReachable) continue;
                        if (cp?.scope==='local' && cp.homeWorldKey && cp.homeWorldKey!==payload.setting?.worldKey && !currentWorldMatchesOrigin(payload.setting)) continue;
                        if (other) ensurePhoneContactProfile(other,{scope:cp?.scope||(payload.setting?.originReachable?'origin':'local'),homeWorldKey:cp?.homeWorldKey||(payload.setting?.originReachable?(s.worldTransit?.origin?.worldKey||payload.setting?.worldKey):payload.setting?.worldKey),availability:'active',source:cp?.source||'wechat-message'});
                    }
                    if (key === 'calls') {
                        const other=compactText(item.author||item.contact,80); const cp=phoneContactProfile(other);
                        if (cp?.scope==='origin' && !payload.setting?.originReachable) continue;
                        if (cp?.scope==='local' && cp.homeWorldKey && cp.homeWorldKey!==payload.setting?.worldKey && !currentWorldMatchesOrigin(payload.setting)) continue;
                    }
                    const stored = stampPhoneEvent({ ...item, _sidecarId:payload.id, _floor:payload.floor },{floor:payload.floor,sidecarId:payload.id,createdAt:payloadCreatedAt});
                    const duplicate = (s.phone[key] || []).slice(-40).some(row => compactText(row?.content,1800) === compactText(stored.content,1800) && compactText(row?.author||row?.contact,100) === compactText(stored.author||stored.contact,100));
                    if (duplicate) continue;
                    s.phone[key].push(stored);
                    if(key==='sms'||key==='calls'){
                        const other=compactText(stored.author||stored.contact,100);if(other){
                            s39MarkAcquaintance(other,{channel:key==='calls'?'Điện thoại':'SMS',floor:payload.floor,evidence:compactText(stored.content||stored.status,220)});
                            s39RecordStoryEvent({type:'communication',relatedId:stored.id,participants:[userName,other],channel:key==='calls'?'Điện thoại':'SMS',status:'Đã xảy ra',summary:`${other}：${compactText(stored.content||stored.status,700)}`,floor:payload.floor,time:stored.time,source:'companion-phone'});
                        }
                    }
                    if (key === 'wechat') {
                        for (const name of [item.author,item.contact]) if (name && name !== userName && !s.phone.contacts.some(contact => (typeof contact === 'string' ? contact : contact.name) === name)) s.phone.contacts.push({ name });
                        const authorIsUser = item.author === userName || item.author === '{{user}}';
                        const contact = compactText(authorIsUser ? item.contact : item.author, 100);
                        if (contact) {
                            s39MarkAcquaintance(contact,{channel:'WeChat',floor:payload.floor,evidence:`Hậu trường đồng bộ WeChat: ${compactText(item.content,220)}`});
                            s39RecordStoryEvent({type:'communication',relatedId:stored.id,participants:[userName,contact],channel:'WeChat',status:'Đã xảy ra',summary:`${contact}：${compactText(item.content||'[Sticker]',700)}`,floor:payload.floor,time:item.time,source:'companion-phone'});
                            const thread = ensurePhoneThread(contact);
                            pushPhoneThreadMessageUnique(thread,{ id:uid(authorIsUser?'phone-user':'phone-ai'), role:authorIsUser?'user':'character', sender:authorIsUser?userName:contact,
                                content:item.content, time:item.time || phoneClock().time, createdAt:stored.createdAt, _eventSeq:stored._eventSeq, _sidecarId:payload.id, _floor:payload.floor },'');
                            normalizePhoneThreadChronology(thread,'');
                        }
                    }
                }
                // S9.4: sổ ghi điện thoại không tự cắt bớt theo dung lượng.
            }
        }
        if (payload.phone.write) {
            s.phone.wechatGroups ||= [];
            s.phone.groupThreads ||= [];
            for (const rawItem of payload.phone.wechatGroups || []) {
                const knownProfile=phoneGroupProfile(rawItem.groupName);
                if (knownProfile?.scope==='origin' && !payload.setting?.originReachable) continue;
                if (knownProfile?.scope==='local' && knownProfile.homeWorldKey && knownProfile.homeWorldKey!==payload.setting?.worldKey && !currentWorldMatchesOrigin(payload.setting)) continue;
                // R9S1P30: lượt này đã nhận hợp lệ tin nhắn của nhóm WeChat đó thì đồng thời khôi phục trạng thái với tới được của nhóm chat tương ứng.
                // Tránh để những nhóm từng bị đánh dấu offline-origin tiếp tục bị lọc khỏi danh sách WeChat.
                if (knownProfile) {
                    if (knownProfile.scope === 'origin' && payload.setting?.originReachable) knownProfile.availability = 'active';
                    else if (knownProfile.scope !== 'origin' && (!knownProfile.homeWorldKey || knownProfile.homeWorldKey === payload.setting?.worldKey) && payload.setting?.available !== false) knownProfile.availability = 'active';
                    knownProfile.updatedAt = Date.now();
                }
                const senderRegistered = rawItem.sender ? (registerNpcIdentity({name:rawItem.sender, source:`wechat-group:${rawItem.groupName||''}`, floor:payload.floor}, payload.floor) || rawItem.sender) : '';
                if (senderRegistered) ensureAmbientNpcPerson(senderRegistered, rawItem.groupName, payload.floor);
                const membersRegistered = (rawItem.members||[]).map(name=>{
                    const canonical = registerNpcIdentity({name, source:`wechat-group:${rawItem.groupName||''}`, floor:payload.floor}, payload.floor)||canonicalNpcName(name)||name;
                    ensureAmbientNpcPerson(canonical, rawItem.groupName, payload.floor);
                    return canonical;
                });
                const item = { ...rawItem, sender:senderRegistered, members:membersRegistered };
                const messageScope=payload.setting?.originReachable?'origin':'local';
                const messageHomeKey=payload.setting?.originReachable?(s.worldTransit?.origin?.worldKey||payload.setting?.worldKey):payload.setting?.worldKey;
                let messageProfile=s.phone.groupProfiles.find(row => compactText(row?.groupName,120) === compactText(item.groupName,120) && compactText(row?.homeWorldKey,120)===compactText(messageHomeKey,120));
                if (!messageProfile) {
                    messageProfile={ id:uid('group-profile'), groupName:item.groupName, type:'other', members:[...(item.members||[])], topic:'', activityLevel:'medium', source:'message-discovered', scope:messageScope, homeWorldKey:messageHomeKey, channelType:'wechat', availability:'active', createdAt:Date.now(), updatedAt:Date.now(), _floor:payload.floor };
                    s.phone.groupProfiles.push(messageProfile);
                } else {
                    messageProfile.channelType='wechat';
                    messageProfile.availability='active';
                    messageProfile.members=[...new Set([...(messageProfile.members||[]),...(item.members||[]),item.sender].map(x=>compactText(x,80)).filter(Boolean))].slice(0,50);
                    messageProfile.updatedAt=Date.now(); messageProfile._floor=payload.floor;
                }
                const stored = stampPhoneEvent({ ...item, _sidecarId:payload.id, _floor:payload.floor, _homeWorldKey:messageHomeKey, _groupScope:messageScope },{floor:payload.floor,sidecarId:payload.id,createdAt:payloadCreatedAt});
                if(stored.sender){
                    s39MarkAcquaintance(stored.sender,{channel:`Nhóm WeChat: ${stored.groupName||''}`,floor:payload.floor,evidence:compactText(stored.content,220)});
                    s39RecordStoryEvent({type:'group-communication',relatedId:stored.id,participants:[userName,stored.sender],channel:`Nhóm WeChat: ${stored.groupName||''}`,status:'Đã xảy ra',summary:`${stored.sender}：${compactText(stored.content||'[Tin nhắn nhóm]',700)}`,floor:payload.floor,time:stored.time,source:'companion-phone'});
                }
                const duplicate = (s.phone.wechatGroups || []).slice(-80).some(row => compactText(row?.groupName,120) === compactText(stored.groupName,120) && compactText(row?.sender,100) === compactText(stored.sender,100) && compactText(row?.content,1800) === compactText(stored.content,1800));
                const gpForThread = messageProfile || phoneGroupProfile(item.groupName);
                const thread = ensurePhoneGroupThread(item.groupName, item.members || [], gpForThread?.homeWorldKey || messageHomeKey || payload.setting?.worldKey || '');
                if (duplicate) {
                    // Dù tin nhắn bị trùng vẫn phải hoàn tất việc tự chữa profile/thread; bản cũ chính là bị kẹt ở lệnh continue chỗ này.
                    const old=(s.phone.wechatGroups||[]).slice().reverse().find(row=>compactText(row?.groupName,120)===compactText(stored.groupName,120)&&compactText(row?.sender,100)===compactText(stored.sender,100)&&compactText(row?.content,1800)===compactText(stored.content,1800));
                    if(old){if(!old._homeWorldKey)old._homeWorldKey=messageHomeKey;if(!old._groupScope)old._groupScope=messageScope;}
                } else s.phone.wechatGroups.push(stored);
                {
                    const senderIsUser = item.sender === userName || item.sender === '{{user}}';
                    pushPhoneThreadMessageUnique(thread,{
                        id:uid(senderIsUser?'group-user':'group-ai'), role:senderIsUser?'user':'character', sender:item.sender || 'Thành viên nhóm',
                        content:item.content, time:item.time || phoneClock().time, createdAt:stored.createdAt, _eventSeq:stored._eventSeq, mentionsUser:Boolean(item.mentionsUser),
                        _sidecarId:payload.id, _floor:payload.floor,
                    },item.groupName||'');
                    normalizePhoneThreadChronology(thread,item.groupName||'');
                }
            }
            // S9.4: lịch sử nhóm WeChat chỉ thêm chứ không bớt, không tự cắt theo dung lượng.
        }
        if (payload.phone.write) {
            s.phone.channelGroups ||= []; s.phone.groupThreads ||= [];
            for (const rawItem of payload.phone.channelGroups || []) {
                const knownProfile=phoneGroupProfile(rawItem.groupName);
                if (knownProfile?.scope==='origin' && !payload.setting?.originReachable) continue;
                if (knownProfile?.scope==='local' && knownProfile.homeWorldKey && knownProfile.homeWorldKey!==payload.setting?.worldKey && !currentWorldMatchesOrigin(payload.setting)) continue;
                const senderRegistered = rawItem.sender ? (registerNpcIdentity({name:rawItem.sender, source:`channel-group:${rawItem.groupName||''}`, floor:payload.floor}, payload.floor) || rawItem.sender) : '';
                if (senderRegistered) ensureAmbientNpcPerson(senderRegistered, rawItem.groupName, payload.floor);
                const membersRegistered=(rawItem.members||[]).map(name=>registerNpcIdentity({name,source:`channel-group:${rawItem.groupName||''}`,floor:payload.floor},payload.floor)||canonicalNpcName(name)||name);
                const item={...rawItem,sender:senderRegistered,members:membersRegistered}; const stored=stampPhoneEvent({...item,_sidecarId:payload.id,_floor:payload.floor},{floor:payload.floor,sidecarId:payload.id,createdAt:payloadCreatedAt});
                if(stored.sender){
                    s39MarkAcquaintance(stored.sender,{channel:`Liên lạc nhóm: ${stored.groupName||''}`,floor:payload.floor,evidence:compactText(stored.content,220)});
                    s39RecordStoryEvent({type:'group-communication',relatedId:stored.id,participants:[userName,stored.sender],channel:`Liên lạc nhóm: ${stored.groupName||''}`,status:'Đã xảy ra',summary:`${stored.sender}：${compactText(stored.content||'[Tin nhắn nhóm]',700)}`,floor:payload.floor,time:stored.time,source:'companion-phone'});
                }
                const duplicate=(s.phone.channelGroups||[]).slice(-80).some(row=>compactText(row?.groupName,120)===compactText(stored.groupName,120)&&compactText(row?.sender,100)===compactText(stored.sender,100)&&compactText(row?.content,1800)===compactText(stored.content,1800));
                if(duplicate)continue; s.phone.channelGroups.push(stored);
                let gp=s.phone.groupProfiles.find(row=>compactText(row?.groupName,120)===compactText(item.groupName,120)&&compactText(row?.homeWorldKey,120)===compactText(payload.setting?.worldKey,120));
                if(!gp){gp={id:uid('group-profile'),groupName:item.groupName,type:'other',members:[...(item.members||[])],topic:'',activityLevel:'medium',source:'Tự lập từ liên lạc nhóm thời đại',scope:'local',homeWorldKey:payload.setting?.worldKey||'',channelType:item.channelType||payload.setting?.communicationType||'terminal',availability:'active',createdAt:Date.now(),updatedAt:Date.now(),_floor:payload.floor};s.phone.groupProfiles.push(gp)}
                const gpForThread=phoneGroupProfile(item.groupName); const thread=ensurePhoneGroupThread(item.groupName,item.members||[],gpForThread?.homeWorldKey||payload.setting?.worldKey||''); if(!thread.messages.some(row=>row._sidecarId===payload.id&&row.sender===item.sender&&row.content===item.content)){thread.messages.push({id:uid('channel-ai'),role:'character',sender:item.sender||'Thành viên',content:item.content,time:item.time||phoneClock().time,createdAt:stored.createdAt,_eventSeq:stored._eventSeq,mentionsUser:Boolean(item.mentionsUser),channelType:item.channelType||payload.setting?.communicationType||'terminal',_sidecarId:payload.id,_floor:payload.floor});thread.updatedAt=Date.now()}
            }
            // S9.4: lịch sử liên lạc nhóm thời đại chỉ thêm chứ không bớt.
        }
        s8ApplyFinanceEvents(payload.phone?.financeEvents || [], payload);
        s39NarrativeShoppingOrders(payload);
        const narrativeOrderCreates=s37NarrativeFoodOrderCreates(payload);
        const mergedOrderCreates=s37MergeStoryOrderCreates(narrativeOrderCreates,payload.phone?.orderCreates || []);
        s12ApplyOrderCreates(mergedOrderCreates,payload);
        s12ApplyOrderUpdates(payload.phone?.orderUpdates || [],payload);
        s12ApplyKnowledgeEvents(payload.phone?.knowledgeEvents || [],payload);
        s12ApplyNpcActivities(payload.phone?.npcActivities || [],payload);
        s12ReconcileCallReceipts();
        s8TickPhoneEcosystem(payload.floor);

        const handled = new Set(payload.phone?.handledPendingIds || []);
        // S6: kể cả khi mô hình quên điền lại handledPendingIds, chỉ cần kết quả liên hệ/nhóm/cuộc gọi tương ứng đã xuất hiện trong đầu ra thì vẫn tự coi là đã xử lý, tránh cảnh “tin nhắn riêng chờ trả lời mãi mãi”.
        for (const pendingItem of s.phone.pendingOutgoing || []) {
            const target = compactText(pendingItem?.contact || pendingItem?.groupName, 120);
            if (!target) continue;
            let resolved = false;
            if (pendingItem.type === 'wechat-group' || pendingItem.type === 'channel-group' || pendingItem.groupName) {
                resolved = [...(payload.phone?.wechatGroups||[]), ...(payload.phone?.channelGroups||[])].some(row => compactText(row?.groupName,120) === target);
            } else if (pendingItem.type === 'outgoing-call' || pendingItem.type === 'call-action') {
                resolved = (payload.phone?.calls||[]).some(row => [row?.author,row?.contact].some(name => compactText(name,120) === target));
            } else {
                resolved = [...(payload.phone?.wechat||[]), ...(payload.phone?.sms||[])].some(row => [row?.author,row?.contact].some(name => compactText(name,120) === target));
            }
            if (resolved) handled.add(pendingItem.id);
        }
        if (handled.size) s.phone.pendingOutgoing = (s.phone.pendingOutgoing || []).filter(item => !handled.has(item.id));

        if (payload.world.write) {
            const world = s.characterWorld;
            payload.world.events.forEach(event => {
                const canonical = registerNpcIdentity({ name:event.character, source:event.source || 'world-event', floor:payload.floor }, payload.floor) || event.character;
                const participants=[...new Set([canonical,...(event.participants||[])].map(value=>relationPartyName(value)).filter(Boolean))].slice(0,12),knownBy=[...new Set([...(event.knownBy||[]),...participants].map(value=>relationPartyName(value)).filter(Boolean))].slice(0,24);
                const storedEvent = { ...event, character:canonical, participants, knownBy, userKnows:Boolean(event.userKnows), _sidecarId:payload.id, _floor:payload.floor };
                world.events.push(storedEvent);
                s39RecordStoryEvent({type:'offscreen-world',relatedId:storedEvent.id,participants,knownBy,userKnows:storedEvent.userKnows,channel:'Bỉ Gian Tư Văn/hiện thực ngoài ống kính',status:'Đã xảy ra',summary:`${canonical} | ${storedEvent.activity}${storedEvent.social?` | Giao tiếp: ${storedEvent.social}`:''}${storedEvent.goal?` | Mục tiêu: ${storedEvent.goal}`:''}`,floor:payload.floor,time:storedEvent.time,location:storedEvent.location,source:'companion-world'});
                let character = world.characters.find(item => item.name === storedEvent.character);
                if (!character) { character={ id:uid('character'), name:storedEvent.character, location:'', activity:'', goal:'', mood:'', social:'', updatedAt:'', time:'', lastFloor:-1, updates:0 }; world.characters.push(character); }
                character.location=storedEvent.location||character.location; character.activity=storedEvent.activity||character.activity; character.goal=storedEvent.goal||character.goal;
                character.mood=storedEvent.mood||character.mood; character.social=storedEvent.social||character.social; character.time=storedEvent.time||character.time;
                character.updatedAt=payload.generatedAt; character.lastFloor=payload.floor; character.updates=Number(character.updates||0)+1;
            });
            world.lastGeneratedAt=payload.generatedAt; world.lastFloor=payload.floor;
        }
        const incoming = (payload.phone?.calls || []).find(call => !s12CallIsResolved(call) && call?.requiresAnswer && ['incoming','ringing','waiting'].includes(call?.status));
        if (incoming) setTimeout(() => showIncomingCallOverlay(incoming, payload.floor), 260);
    }

    function rebuildCharacterWorldFromEvents() {
        const world = stateRuntime.state.characterWorld;
        const previous = new Map((world.characters || []).map(item => [item.name, item]));
        const characters = [];
        for (const event of world.events || []) {
            let character = characters.find(item => item.name === event.character);
            if (!character) {
                character = { ...(previous.get(event.character) || {}), id: previous.get(event.character)?.id || uid('character'), name: event.character, location: '', activity: '', goal: '', mood: '', social: '', updatedAt: '', time: '', lastFloor: -1, updates: 0 };
                characters.push(character);
            }
            character.location = event.location || character.location;
            character.activity = event.activity || character.activity;
            character.goal = event.goal || character.goal;
            character.mood = event.mood || character.mood;
            character.social = event.social || character.social;
            character.time = event.time || character.time;
            character.updatedAt = event.generatedAt || character.updatedAt;
            character.lastFloor = Math.max(Number(character.lastFloor || -1), Number(event.floor ?? event._floor ?? -1));
            character.updates = Number(character.updates || 0) + 1;
        }
        world.characters = characters;
        const last = (world.events || []).at(-1);
        world.lastGeneratedAt = last?.generatedAt || '';
        world.lastFloor = last?.floor ?? last?._floor ?? -1;
    }

    function removeCompanionPayload(payload) {
        if (!payload?.id) return;
        // S9.4: một khi lịch sử đã vào điện thoại thì nó tách khỏi sidecar của chính văn và trở thành bản ghi liên lạc vĩnh viễn.
        // Việc tạo lại, sắp xếp tầng trùng, dọn sidecar của lời mở đầu hay xóa chính văn đều không được tự xóa bản ghi WeChat/chat nhóm/SMS/cuộc gọi/thanh toán nữa.
        // Chỉ khi người dùng chủ động xóa/dọn trong điện thoại, hoặc chọn rõ “xóa một chạm dữ liệu hoạt động của cuộc trò chuyện này” thì mới được phép xóa.
        stateRuntime.state.storyExtras ||= { moments:[], diary:[], anniversaries:[] };
        rollbackMomentReactionPayload(payload.id);
        for (const key of ['moments','diary','anniversaries']) stateRuntime.state.storyExtras[key] = (stateRuntime.state.storyExtras[key] || []).filter(item => item?._sidecarId !== payload.id);
        rollbackAppearancePayload(payload.id);
        const ids = new Set((payload.world?.events || []).map(item => item.id).filter(Boolean));
        stateRuntime.state.characterWorld.events = (stateRuntime.state.characterWorld.events || []).filter(item => item?._sidecarId !== payload.id && !ids.has(item.id));
        rebuildCharacterWorldFromEvents();
    }
    async function saveChatExtras(scope=captureChatScope()) {
        if(!chatScopeIsCurrent(scope))return false;
        try {
            const module=await import('/script.js');
            if(!chatScopeIsCurrent(scope))return false;
            if(typeof module.saveChatConditional==='function'){await module.saveChatConditional();return chatScopeIsCurrent(scope);}
        } catch (error) { if(chatScopeIsCurrent(scope))console.warn('[vvv Sân Khấu Nhỏ] Nhập saveChatConditional thất bại',error); }
        if(!chatScopeIsCurrent(scope))return false;
        try { await context()?.saveChat?.(); return chatScopeIsCurrent(scope); }
        catch (error) { if(chatScopeIsCurrent(scope))console.warn('[vvv Sân Khấu Nhỏ] Lưu dữ liệu mở rộng của tin nhắn thất bại',error);return false; }
    }

    function sidecarPayloadForFloor(floor) {
        return context()?.chat?.[floor]?.extra?.vvvTheaterCompanion || null;
    }

    function phoneItems(payload) {
        // r4: phần “thiết bị liên lạc” dưới chính văn bắt buộc phải là cùng một mớ dữ liệu của lượt này mà điện thoại đầy đủ đang thấy.
        // r3 đã ghi được nhóm WeChat vào iPhone17Promax, nhưng đoạn mã cũ ở đây chỉ liệt kê wechat/sms/calls,
        // khiến tin nhắn nhóm chỉ thấy trong điện thoại còn thẻ gập bảy điều lại hiện “Lượt này không có cập nhật”. Ở đây đưa wechatGroups vào chính thức.
        const result = [];
        for (const item of payload.phone?.wechat || []) {
            result.push({ ...item, type:'wechat', label:'WeChat', icon:'💚' });
        }
        for (const item of payload.phone?.wechatGroups || []) {
            result.push({
                ...item,
                // Dòng đầu của thẻ gập ưu tiên hiện tên nhóm, dòng thứ hai mới ghi thành viên đã phát biểu.
                author: item.groupName || item.author || 'Nhóm WeChat',
                contact: item.sender || item.contact || '',
                type:'wechatGroups',
                label:`Nhóm WeChat${item.sender ? ` · ${item.sender}` : ''}`,
                icon:'👥',
            });
        }
        for (const item of payload.phone?.sms || []) {
            result.push({ ...item, type:'sms', label:'SMS', icon:'✉️' });
        }
        for (const item of payload.phone?.calls || []) {
            result.push({ ...item, type:'calls', label:(supportsLiveCalls()?'Cuộc gọi':'Nhật ký liên lạc'), icon:'📞' });
        }
        return result;
    }

    function companionUiState(floor) {
        const message = context()?.chat?.[floor];
        if (!message) return { phoneExpanded: false, worldExpanded: false, sections: {} };
        message.extra = message.extra && typeof message.extra === 'object' ? message.extra : {};
        message.extra.vvvTheaterUi = message.extra.vvvTheaterUi && typeof message.extra.vvvTheaterUi === 'object'
            ? message.extra.vvvTheaterUi
            : { phoneExpanded: false, worldExpanded: false, sections: {} };
        const ui = message.extra.vvvTheaterUi;
        if (!ui.sections || typeof ui.sections !== 'object' || Array.isArray(ui.sections)) ui.sections = {};
        return ui;
    }

    function unresolvedPromiseSnapshot(payload) {
        const payloadPromises = (Array.isArray(payload?.promises) ? payload.promises : [])
            .filter(item => promiseContentIsConcrete(item?.content ?? item?.['Nội dung lời hẹn'], item))
            .filter(item => !promiseClosedStatus(item?.status ?? item?.['Trạng thái']))
            .map(item => {
                const row = promiseRowForItem(item);
                // A manual click closes the canonical row even if an older
                // sidecar still carries the promise as pending.
                if (row && promiseClosedStatus(row['Trạng thái'])) return null;
                if (!row) return item;
                const id = promiseEntityId(row, { create: true });
                return {
                    ...item,
                    promiseId: item.promiseId || id,
                    _entityId: item._entityId || id,
                    time: item.time || item['Thời điểm hẹn'] || row['Thời điểm hẹn'] || '',
                    content: item.content || item['Nội dung lời hẹn'] || row['Nội dung lời hẹn'] || '',
                    characters: item.characters || item['Nhân vật cốt lõi'] || row['Nhân vật cốt lõi'] || '',
                    status: row['Trạng thái'] || item.status || item['Trạng thái'] || 'Chờ thực hiện',
                };
            })
            .filter(Boolean);
        if (payloadPromises.length) return payloadPromises;
        return (stateRuntime.state?.tables?.promises || []).filter(row => !promiseClosedStatus(row['Trạng thái'])).slice(-8).map(row => ({
            promiseId: promiseEntityId(row, { create: true }),
            _entityId: promiseEntityId(row),
            time: row['Thời điểm hẹn'] || '',
            content: row['Nội dung lời hẹn'] || '',
            characters: row['Nhân vật cốt lõi'] || '',
            status: row['Trạng thái'] || 'Chờ thực hiện',
        }));
    }

    function secretSnapshot(payload) {
        if ((payload?.secrets || []).length) return payload.secrets;
        return (stateRuntime.state?.secrets || []).slice(-8);
    }

    function sceneSnapshot(payload) {
        const merged = { ...(stateRuntime.state?.scene || {}), ...(payload?.scene || {}) };
        const latest=Math.max(0,(context()?.chat?.length||1)-1);
        if(payload?.scene?.time&&Number(payload?.floor)>=Math.max(0,latest-8)&&!narrativeSupportsSceneTime(payload.scene.time)) merged.time=pruneUnsupportedSceneTimePrecision(payload.scene.time);
        if(activeTimeCalibration())merged.time=effectiveStoryTime();
        return Object.fromEntries(Object.entries(merged).filter(([, value]) => String(value || '').trim()));
    }

    function foldBlock(title, meta, body, key, floor) {
        const ui = companionUiState(floor);
        const open = Boolean(ui.sections?.[key]);
        return `<section class="vvvtm-info-fold" data-vvvtm-fold-key="${esc(key)}"><div class="vvvtm-world-fold-toggle"><span>${title}</span><em>${esc(meta || '')}</em><button type="button" class="vvvtm-fold-sign" data-vvvtm-toggle-section="${esc(key)}" data-vvvtm-floor="${esc(floor)}" aria-expanded="${open}" aria-label="${open ? 'Thu gọn' : 'Mở'}${esc(String(title).replace(/^\S+\s*/, ''))}">${open ? '－' : '＋'}</button></div><div class="vvvtm-info-fold-body" ${open ? '' : 'hidden'}>${body}</div></section>`;
    }

    function companionDisplayProfile(payload) {
        const stored=payload?.setting || stateRuntime.state?.communicationProfile || inferCurrentWorldContext();
        const latest=Math.max(0,(context()?.chat?.length||1)-1);
        const floor=Number(payload?.floor);
        // Tám tầng mới nhất thuộc về hiện thực hiện tại: tự chữa state trước, rồi mới dựng bằng canonical profile, tránh để sidecar cũ
        // ghi đè các trường “tiền hiện đại/năm 1000/thư từ qua lại” lên năm và phương thức liên lạc hiện đại mà chính văn vừa xác nhận.
        if (Number.isFinite(floor) && floor>=Math.max(0,latest-8)) {
            selfHealCommunicationReality({floor});
            return stateRuntime.state?.communicationProfile || stored;
        }
        return stored;
    }


    function renderCompanionInline(payload) {
        const phone = phoneItems(payload);
        const world = payload.world?.events || [];
        const appearances = payload.appearances || [];
        const story = payload.story || { moments:[], diary:[], anniversaries:[] };
        const promises = unresolvedPromiseSnapshot(payload);
        const secrets = secretSnapshot(payload);
        const scene = sceneSnapshot(payload);
        const always = Boolean(stateRuntime.state?.settings?.companionAlwaysShowShell);
        if (!always && !phone.length && !world.length && !appearances.length && !promises.length && !secrets.length && !Object.keys(scene).length && !story.moments?.length && !story.diary?.length && !story.anniversaries?.length) return '';

        const ui = companionUiState(payload.floor);
        const phoneOpen = Boolean(ui.phoneExpanded);
        const worldOpen = Boolean(ui.worldExpanded);
        const profile = companionDisplayProfile(payload);
        const device = communicationLabel({setting:profile});
        const callStatus = { incoming:'Cuộc gọi đến', ringing:'Đang gọi', waiting:'Đang chờ nghe máy', missed:'Cuộc gọi nhỡ', connected:'Đang gọi', ended:'Đã kết thúc', outgoing:'Đã gọi đi' };

        const phoneBody = phone.length
            ? phone.slice(0, 10).map(item => {
                const callMeta = item.type === 'calls'
                    ? `${callStatus[item.status] || 'Cuộc gọi'}${item.requiresAnswer ? ' · đang chờ bạn bắt máy' : ''}`
                    : item.label;
                const actions = item.type === 'calls' && item.requiresAnswer
                    ? `<div class="vvvtm-call-actions"><button type="button" data-vvvtm-call-action="answer" data-vvvtm-call-id="${esc(item.id)}" data-vvvtm-call-contact="${esc(item.author || item.contact || '')}">Nghe máy</button><button type="button" class="danger-soft" data-vvvtm-call-action="decline" data-vvvtm-call-id="${esc(item.id)}" data-vvvtm-call-contact="${esc(item.author || item.contact || '')}">Cúp máy</button></div>`
                    : '';
                return `<article class="vvvtm-inline-phone-item ${item.type === 'calls' ? 'call' : ''}"><span>${esc(item.icon)}</span><div><b>${esc(item.author || item.contact || item.label)}</b><small>${esc([callMeta,displayGeneratedEventTime(item,payload.floor)].filter(Boolean).join(' · '))}</small><p>${esc(item.content)}</p>${actions}</div></article>`;
            }).join('')
            : `<div class="vvvtm-inline-empty">${profile.available === false && profile.communicationType === 'smartphone' ? `Mạng hiện đang ngoại tuyến: vẫn mở được ${esc(device)} để xem nội dung trong máy; WeChat, SMS, cuộc gọi và các cách liên lạc từ xa tạm thời không dùng được.` : profile.available === false ? `Phán định của không - thời gian hiện tại: ${esc(device)} chưa có phương tiện liên lạc từ xa khả dụng; sẽ không nhồi nội dung lệch thời đại.` : `Lượt này không có nội dung mới hợp lý cho ${esc(device)}.`}</div>`;

        const worldBody = world.length
            ? `${payload.world.timeProgress ? `<div class="vvvtm-world-progress">⏱ ${esc(payload.world.timeProgress)}</div>` : ''}${world.map(item => `<article class="vvvtm-inline-world-item"><header><b>${esc(item.character)}</b><small>${esc([item.time,item.location].filter(Boolean).join(' · '))}</small></header><p>${esc(item.activity)}</p><dl>${item.goal ? `<div><dt>Mục tiêu</dt><dd>${esc(item.goal)}</dd></div>` : ''}${item.mood ? `<div><dt>Trạng thái</dt><dd>${esc(item.mood)}</dd></div>` : ''}${item.social ? `<div><dt>Giao tiếp</dt><dd>${esc(item.social)}</dd></div>` : ''}${item.relationToMainPlot ? `<div><dt>Quan hệ mạch chính</dt><dd>${esc(item.relationToMainPlot)}</dd></div>` : ''}</dl></article>`).join('')}`
            : '<div class="vvvtm-inline-empty">Lượt này không có thay đổi nhân vật ngoài ống kính cần ghi lại.</div>';

        const sceneLabels = {time:'Thời gian',location:'Địa điểm',weather:'Thời tiết',mood:'Không khí',pace:'Nhịp',goal:'Mục tiêu lượt này'};
        const sceneBody = Object.entries(scene).length
            ? `<dl class="vvvtm-inline-kv">${Object.entries(scene).map(([key,value]) => `<div><dt>${esc(sceneLabels[key] || key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`
            : '<div class="vvvtm-inline-empty">Lượt này chưa nhận diện được thông tin bối cảnh mới.</div>';

        const promiseBody = promises.length
            ? promises.map(item => {
                const row = promiseRowForItem(item);
                const promiseId = promiseEntityId(row) || promiseObjectId(item);
                const promiseKey = promiseSemanticKey(promiseRecordContent(item), promiseRecordCharacters(item));
                const content = promiseRecordContent(item);
                const characters = promiseRecordCharacters(item);
                const time = compactText(item?.time ?? item?.['Thời điểm hẹn'], 220);
                const action = `<div class="vvvtm-row-actions"><button type="button" class="vvvtm-promise-complete" data-vvvtm-promise-complete="true"${promiseId ? ` data-vvvtm-promise-id="${esc(promiseId)}"` : ''}${promiseKey && promiseKey !== '::' ? ` data-vvvtm-promise-key="${esc(promiseKey)}"` : ''} data-vvvtm-promise-content="${esc(content)}" data-vvvtm-promise-characters="${esc(characters)}" data-vvvtm-promise-time="${esc(time)}" data-vvvtm-promise-floor="${esc(payload.floor)}" aria-label="Hoàn thành lời hẹn: ${esc(content || 'Lời hẹn chưa đặt tên')}" title="Đánh dấu đã hoàn thành ngay">Hoàn thành</button></div>`;
                return `<article class="vvvtm-inline-simple"${promiseId ? ` data-vvvtm-promise-id="${esc(promiseId)}"` : ''}><b>${esc(content)}</b><small>${esc([time, characters, item.status || item['Trạng thái']].filter(Boolean).join(' · '))}</small>${action}</article>`;
            }).join('')
            : '<div class="vvvtm-inline-empty">Hiện không có lời hẹn nào chờ thực hiện.</div>';

        const secretBody = secrets.length
            ? secrets.map(item => `<article class="vvvtm-inline-simple"><b>${esc(item.subject || 'Bí mật')}</b><p>${esc(item.content || '')}</p>${item.knowers ? `<small>Người biết: ${esc(item.knowers)}</small>` : ''}${item.suspects ? `<small>Người nghi ngờ: ${esc(item.suspects)}</small>` : ''}</article>`).join('')
            : '<div class="vvvtm-inline-empty">Hiện không có lời hẹn và bí mật nào cần hiển thị.</div>';

        const appearanceBody = appearances.length
            ? appearances.map(item => `<article class="vvvtm-inline-appearance"><header><b>${esc(item.character)}</b><small>${esc([item.time,item.location].filter(Boolean).join(' · '))}</small></header><p>${esc(item.outfit)}</p><dl>${item.hair ? `<div><dt>Kiểu tóc</dt><dd>${esc(item.hair)}</dd></div>` : ''}${item.accessories ? `<div><dt>Phụ kiện</dt><dd>${esc(item.accessories)}</dd></div>` : ''}${item.shoes ? `<div><dt>Giày dép</dt><dd>${esc(item.shoes)}</dd></div>` : ''}${item.condition ? `<div><dt>Trạng thái</dt><dd>${esc(item.condition)}</dd></div>` : ''}</dl></article>`).join('')
            : '<div class="vvvtm-inline-empty">Lượt này không có thông tin trang phục mới.</div>';

        const storyBody = (items, emptyText) => items?.length
            ? items.map(item => `<article class="vvvtm-inline-simple"><b>${esc(item.author || item.contact || '')}</b><p>${esc(item.content || '')}</p><small>${esc(displayGeneratedEventTime(item,payload.floor))}</small></article>`).join('')
            : `<div class="vvvtm-inline-empty">${esc(emptyText)}</div>`;

        const policySourceName = ['tavern-current-preset','companion-independent-then-tavern'].includes(payload.source) ? 'Nhà cung cấp API chính của SillyTavern từ yêu cầu bản cũ' : 'Nhà cung cấp API riêng';
        const status = payload.parseStatus === 'ok' || payload.parseStatus === 'fallback-ok'
            ? '<div class="vvvtm-inline-success">Đã tạo xong! ♡</div>'
            : payload.parseStatus === 'retrying-seven-api'
                ? `<div class="vvvtm-inline-warning">Bảy điều hậu trường tạm thời thất bại, đang tự động thử lại (lần ${Math.max(1, Number(payload.retryAttempt || 1))}) ; lý do: ${esc(payload.retryReason || 'lỗi mạng hoặc định dạng tạm thời')}. Thành công sẽ tự động ghi vào.</div>`
                : ['seven-api-failed','fallback-failed'].includes(payload.parseStatus)
                    ? payload.failureKind === 'provider-policy-refusal'
                        ? `<div class="vvvtm-inline-warning">${esc(policySourceName)} từ chối theo chính sách, lượt này đã dừng ngay và sẽ không tự đổi tuyến: ${esc(payload.fallbackError || 'Yêu cầu bị chính sách nội dung của nhà cung cấp từ chối')}. Bạn có thể vào “API và mô hình” để chọn thủ công một nguồn viết khác.</div>`
                        : `<div class="vvvtm-inline-warning">Bảy điều hậu trường đã dừng tự thử lại: ${esc(payload.fallbackError || 'Phát hiện lỗi cấu hình cần sửa thủ công')}.</div>`
                    : ['waiting-seven-api','missing'].includes(payload.parseStatus)
                        ? '<div class="vvvtm-inline-warning">Lượt này đang tạo Bảy điều hậu trường ở nền; chính văn hiển thị không bị ảnh hưởng.</div>'
                        : payload.parseStatus === 'seven-api-unconfigured'
                            ? `<div class="vvvtm-inline-warning">${esc(payload.fallbackError || 'Nguồn viết của Bảy điều hậu trường không dùng được')}; chính văn hiển thị vẫn bình thường, nhưng mô-đun hậu trường của lượt này sẽ không cập nhật. Hãy vào “API và mô hình” để kiểm tra nguồn viết hiện tại.</div>`
                            : payload.parseStatus === 'invalid'
                                ? '<div class="vvvtm-inline-warning">API Bảy điều hậu trường trả về định dạng bất thường; R9S1P41 sẽ tự thử tiếp khi tạo lại.</div>'
                                : '';

        const ecologyStatus = payload.ecologyRepairStatus === 'ok'
            ? `<div class="vvvtm-inline-success">📡 Đã hồi sinh hệ sinh thái xã hội: ${esc(payload.ecologyRepairReason || 'Điện thoại/Bỉ Gian Tư Văn đã chạm ngưỡng im lặng')}。</div>`
            : payload.ecologyRepairStatus === 'failed'
                ? `<div class="vvvtm-inline-warning">📡 Hồi sinh hệ sinh thái xã hội thất bại: ${esc(payload.ecologyRepairError || 'API bảy điều chưa hoàn tất')}; chính văn và ký ức hiện có không bị ảnh hưởng.</div>`
                : '';
        const completenessStatus = payload.completenessRepair?.attempted && payload.completenessRepair?.status === 'ok'
            ? `<div class="vvvtm-inline-success">🧩 Đã tự bổ sung các mục còn thiếu: ${esc((payload.completenessRepair.missingBefore || []).map(item=>item?.label).filter(Boolean).join(', ') || 'mục đời sống hậu trường')}.</div>`
            : '';
        const memoryGap=companionCoreMemoryGaps({limit:120}).find(item=>Number(item.floor)===Number(payload.floor)&&item.signature&&payload.signature&&item.signature===payload.signature);
        const memoryStatus=memoryGap
            ? `<div class="vvvtm-inline-warning vvvtm-memory-gap">🧠 Bảy điều hậu trường đã tạo xong, nhưng ký ức chính của tầng này chưa được sắp xếp.<button type="button" data-vvvtm-memory-reextract="${esc(payload.floor)}">Dựng lại ký ức chính của tầng này</button></div>`
            : '';
        const calibration=activeTimeCalibration();
        const latestSidecarFloor=(context()?.chat||[]).reduce((last,message,index)=>message?.extra?.vvvTheaterCompanion?index:last,-1);
        const canCalibrate=Number(payload.floor)===latestSidecarFloor;
        const timeLabel=calibration?.value || profile.era || 'Chưa ghi chú thời đại';
        const reasonLabel=calibration?'Đã hiệu chỉnh thủ công':profile.reason;
        const settingNote = `<div class="vvvtm-setting-chip"><span>🌐 ${esc(profile.worldType || 'Tự nhận diện')} · ${esc(timeLabel)} · ${esc(device)}${reasonLabel ? ` · ${esc(reasonLabel)}` : ''}</span>${canCalibrate?'<button type="button" data-vvvtm-time-calibrate title="Tự chỉnh thời gian cốt truyện">🕒 Chỉnh giờ</button>':''}</div>`;
        return `<section class="vvvtm-inline-extra" data-vvvtm-sidecar="${esc(payload.id)}" data-vvvtm-floor="${esc(payload.floor)}">
            <header><span>✒️ 0-32 · 永不落幕的剧场</span><div><button type="button" data-vvvtm-open-tab="worldlife">Quản lý Bỉ Gian Tư Văn</button><button type="button" data-vvvtm-regenerate="${payload.floor}">Viết lại riêng (thêm một yêu cầu)</button></div></header>
            ${status}${memoryStatus}${completenessStatus}${ecologyStatus}${settingNote}
            ${foldBlock('🎬 Cảnh hiện tại', Object.keys(scene).length ? `${Object.keys(scene).length} mục` : 'Không có cập nhật', sceneBody, 'scene', payload.floor)}
            ${foldBlock('⏰ Lời hẹn chờ thực hiện', promises.length ? `${promises.length} mục` : 'Chưa có', promiseBody, 'promises', payload.floor)}
            ${foldBlock('🔐 Lời hẹn và bí mật', secrets.length ? `${secrets.length} mục` : 'Chưa có', secretBody, 'secrets', payload.floor)}
            ${foldBlock('👗 Ngoại hình nhân vật', appearances.length ? `${appearances.length} người` : 'Lượt này không có cập nhật', appearanceBody, 'appearance', payload.floor)}
            ${foldBlock('🌐 Khoảnh khắc', story.moments?.length ? `${story.moments.length} mục` : 'Chưa có', storyBody(story.moments, 'Lượt này không có bài đăng Khoảnh khắc.'), 'moments', payload.floor)}
            ${foldBlock('📔 Nhật ký', story.diary?.length ? `${story.diary.length} mục` : 'Chưa có', storyBody(story.diary, 'Lượt này không có nhật ký cần ghi lại.'), 'diary', payload.floor)}
            ${foldBlock('🗓️ Ngày kỷ niệm', story.anniversaries?.length ? `${story.anniversaries.length} mục` : 'Chưa có', storyBody(story.anniversaries, 'Lượt này không có thông tin ngày kỷ niệm mới.'), 'anniversaries', payload.floor)}
            <section class="vvvtm-phone-fold"><div class="vvvtm-world-fold-toggle"><span>${communicationIcon(profile)} ${esc(device)}</span><em>${phone.length ? `${phone.length} nội dung mới` : 'Lượt này không có cập nhật'}</em><button type="button" class="vvvtm-fold-sign" data-vvvtm-toggle-phone="${payload.floor}" aria-expanded="${phoneOpen}" aria-label="${phoneOpen ? `Thu gọn ${esc(device)}` : `Mở ${esc(device)}`}">${phoneOpen ? '－' : '＋'}</button></div><div class="vvvtm-world-fold-body" ${phoneOpen ? '' : 'hidden'}>${phoneBody}<button type="button" class="vvvtm-open-device-inline" data-vvvtm-open-phone="${payload.floor}">Mở đầy đủ ${esc(device)}</button></div></section>
            <section class="vvvtm-world-fold"><div class="vvvtm-world-fold-toggle"><span>🌍 Bỉ Gian Tư Văn</span><em>${world.length ? `${world.length} bài đăng` : 'Lượt này không có cập nhật'}</em><button type="button" class="vvvtm-fold-sign" data-vvvtm-toggle-world="${payload.floor}" aria-expanded="${worldOpen}" aria-label="${worldOpen ? 'Thu gọn Bỉ Gian Tư Văn' : 'Mở Bỉ Gian Tư Văn'}">${worldOpen ? '－' : '＋'}</button></div><div class="vvvtm-world-fold-body" ${worldOpen ? '' : 'hidden'}>${worldBody}</div></section>
        </section>`;
    }

    function messageNodeForFloor(floor) {
        return document.querySelector(`#chat .mes[mesid="${floor}"],#chat .mes[data-mesid="${floor}"]`);
    }

    function showCompanionLoading(floor, { label='0-32 đang xử lý…', progress=null, detail='' } = {}) {
        if (!stateRuntime.state?.settings?.companionShowLoading) return;
        const node = messageNodeForFloor(floor); const text = node?.querySelector('.mes_text'); if (!text) return;
        let loading = text.querySelector('.vvvtm-inline-loading');
        if (!loading) { loading=document.createElement('div'); loading.className='vvvtm-inline-loading'; text.append(loading); }
        const numeric = Number(progress);
        const determinate = Number.isFinite(numeric) && numeric >= 0 && numeric <= 100;
        const pct = determinate ? Math.max(0,Math.min(100,numeric)) : 0;
        loading.classList.toggle('indeterminate', !determinate);
        loading.innerHTML = `<div class="vvvtm-fallback-progress-head"><b>${esc(label)}</b>${determinate?`<em>${pct}%</em>`:'<em>Đang xử lý</em>'}</div><div class="vvvtm-fallback-progress-track"><i${determinate?` style="width:${Math.max(2,pct)}%"`:''}></i></div>${detail?`<small>${esc(detail)}</small>`:''}`;
    }
    function companionProgressPhase(value) {
        if (value < 18) return 'Đang sắp xếp chính văn và hồ sơ nhân vật của lượt này';
        if (value < 42) return 'Đang đọc ký ức có hạn và hiện thực hiện tại';
        if (value < 70) return 'Đang tạo động thái điện thoại, lời hẹn và nhân vật';
        if (value < 90) return 'Đang đối chiếu định dạng và quy tắc xuyên không - thời gian';
        return 'Đang ghi nội dung hậu trường của lượt này';
    }
    function stopCompanionProgress(floor) {
        const timer=stateRuntime.fallbackProgressTimers.get(Number(floor));
        if(timer)clearInterval(timer);
        stateRuntime.fallbackProgressTimers.delete(Number(floor));
        stateRuntime.fallbackProgressValues.delete(Number(floor));
    }
    function companionWaitingDetail(elapsedSeconds) {
        if (elapsedSeconds < 3) return 'Đã gửi yêu cầu, đang chờ mô hình phản hồi';
        if (elapsedSeconds < 15) return 'Mô hình đang xử lý, đang chờ kết quả có cấu trúc';
        return 'Thời gian phản hồi hơi lâu, vẫn đang chờ mô hình trả về; đây không phải phần trăm tiến độ từ máy chủ';
    }
    function startCompanionProgress(floor, label, detail='') {
        const key=Number(floor); stopCompanionProgress(key);
        const startedAt=Date.now(); stateRuntime.fallbackProgressValues.set(key,0);
        showCompanionLoading(key,{progress:null,label,detail:detail||companionWaitingDetail(0)});
        const timer=setInterval(()=>{
            if(!messageNodeForFloor(key)){stopCompanionProgress(key);return;}
            const elapsed=Math.max(0,(Date.now()-startedAt)/1000);
            showCompanionLoading(key,{progress:null,label,detail:detail||companionWaitingDetail(elapsed)});
        },700);
        stateRuntime.fallbackProgressTimers.set(key,timer);
    }
    function updateCompanionFallbackProgress(floor, progress, label, detail='') {
        const numeric=Number(progress);
        const current=stateRuntime.fallbackProgressValues.get(Number(floor));
        const value=Number.isFinite(numeric)?numeric:(Number.isFinite(current)?Math.floor(current):4);
        if(Number.isFinite(numeric))stateRuntime.fallbackProgressValues.set(Number(floor),numeric);
        showCompanionLoading(floor,{progress:null,label,detail:detail||companionProgressPhase(value)});
    }
    function clearCompanionLoading(floor) {
        stopCompanionProgress(floor);
        messageNodeForFloor(floor)?.querySelectorAll('.vvvtm-inline-loading').forEach(node => node.remove());
    }

    function decorateCompanionActions(card) {
        const actions=card?.querySelector('header>div');
        const configuredButton=actions?.querySelector('[data-vvvtm-regenerate]');
        if(configuredButton)configuredButton.title='Viết lại bằng API riêng của Bảy điều hậu trường';
        actions?.querySelectorAll('[data-vvvtm-regenerate-tavern]').forEach(button=>button.remove());
    }

    function decorateCompanionOutput(floor) {
        const payload = sidecarPayloadForFloor(floor);
        const node = messageNodeForFloor(floor);
        const text = node?.querySelector('.mes_text');
        if (!text) return;
        text.querySelectorAll('.vvvtm-inline-extra').forEach(existing => existing.remove());
        clearCompanionLoading(floor);
        const html = payload ? renderCompanionInline(payload) : '';
        if (html) {
            text.insertAdjacentHTML('beforeend', html);
            const card=[...text.querySelectorAll('.vvvtm-inline-extra')].find(item=>String(item.dataset.vvvtmFloor||'')===String(floor));
            decorateCompanionActions(card);
        }
    }

    function ensureCompanionOutput(floor) {
        const numeric=Number(floor);
        if(!Number.isFinite(numeric))return;
        const payload=sidecarPayloadForFloor(numeric);
        if(!payload)return;
        const text=messageNodeForFloor(numeric)?.querySelector('.mes_text');
        if(!text)return;
        const existing=[...text.querySelectorAll('.vvvtm-inline-extra')].find(node=>String(node.dataset.vvvtmFloor||'')===String(numeric));
        if(existing&&String(existing.dataset.vvvtmSidecar||'')===String(payload.id||'')){decorateCompanionActions(existing);return;}
        decorateCompanionOutput(numeric);
    }

    function decorateAllCompanionOutputs() {
        // Chỉ dùng cho những lần khôi phục toàn bộ một lần rõ ràng như “mở/đổi cuộc trò chuyện”; không còn được bộ hẹn giờ định kỳ gọi lặp lại.
        const chat=context()?.chat||[];
        chat.forEach((message,floor)=>{if(message?.extra?.vvvTheaterCompanion)ensureCompanionOutput(floor);});
    }

    function floorFromMessageNode(node) {
        const mes=node?.matches?.('.mes')?node:node?.closest?.('.mes');
        if(!mes)return null;
        const value=mes.getAttribute('mesid')??mes.dataset?.mesid;
        const floor=Number(value);
        return Number.isFinite(floor)?floor:null;
    }

    function decorateCompanionOutputsInNode(root) {
        if(!root||root.nodeType!==1)return;
        const candidates=[];
        if(root.matches?.('.mes'))candidates.push(root);
        root.querySelectorAll?.('.mes').forEach(node=>candidates.push(node));
        const seen=new Set();
        for(const node of candidates){
            const floor=floorFromMessageNode(node);
            if(floor===null||seen.has(floor))continue;
            seen.add(floor);ensureCompanionOutput(floor);
        }
    }

    let companionDomObserver=null;
    let companionObservedChat=null;
    function bindCompanionDomObserver() {
        const chatNode=document.getElementById('chat');
        if(chatNode===companionObservedChat&&companionDomObserver)return;
        companionDomObserver?.disconnect();
        companionDomObserver=null;companionObservedChat=chatNode||null;
        if(!chatNode)return;
        companionDomObserver=new MutationObserver(mutations=>{
            const floors=new Set();
            for(const mutation of mutations){
                // Sidecar/loading do chính chúng ta chèn vào sẽ không kích hoạt lần trang trí thứ hai.
                if(mutation.target?.closest?.('.vvvtm-inline-extra,.vvvtm-inline-loading'))continue;
                const targetFloor=floorFromMessageNode(mutation.target);
                if(targetFloor!==null)floors.add(targetFloor);
                for(const node of mutation.addedNodes){
                    if(node?.nodeType!==1)continue;
                    if(node.matches?.('.vvvtm-inline-extra,.vvvtm-inline-loading')||node.closest?.('.vvvtm-inline-extra,.vvvtm-inline-loading'))continue;
                    const direct=floorFromMessageNode(node);if(direct!==null)floors.add(direct);
                    node.querySelectorAll?.('.mes').forEach(mes=>{const floor=floorFromMessageNode(mes);if(floor!==null)floors.add(floor);});
                }
            }
            floors.forEach(floor=>ensureCompanionOutput(floor));
        });
        companionDomObserver.observe(chatNode,{childList:true,subtree:true});
        decorateCompanionOutputsInNode(chatNode);
    }

    function companionWritingMode() {
        return 'independent';
    }

    function companionPayloadSource(mode = companionWritingMode()) {
        return 'companion-independent-api';
    }

    function companionWritingSourceLabel(mode = companionWritingMode()) {
        const model = compactText(stateRuntime.serverConfig?.companion?.model, 160);
        return `API riêng của Bảy điều hậu trường · ${model || 'mô hình tự chọn'} · ranh giới dữ liệu riêng`;
    }

    function isCompanionPayloadSource(value) {
        // Nguồn cũ chỉ dùng để nhận diện các sidecar lịch sử đã ghi trước khi nâng cấp, không được gửi lại yêu cầu cũ tương ứng.
        return ['dedicated-seven-api','tavern-current-preset','tavern-current-preset-manual','relay-shared-api','companion-independent-api','companion-independent-then-tavern'].includes(String(value || ''));
    }

    function companionIndependentApiReady() {
        if (stateRuntime.serverHealth?.companionIndependentConfigured === true) return true;
        const companion = stateRuntime.serverConfig?.companion || {};
        const provider = String(companion.provider || 'openai-compatible').toLowerCase();
        const model = String(companion.model || '').trim();
        if (!model) return false;
        if (provider === 'anthropic' || provider === 'gemini') return true;
        return Boolean(String(companion.baseUrl || '').trim());
    }

    async function ensureCompanionIndependentApiReady() {
        if (!companionIndependentApiReady()) {
            try { await refreshServerState({ config:true }); } catch {}
        }
        if (!companionIndependentApiReady()) throw new Error('Chưa cấu hình API riêng cho Bảy điều hậu trường; hãy vào “API và mô hình” điền endpoint chuyên dụng rồi chọn mô hình');
        return stateRuntime.serverConfig?.companion || {};
    }

    async function ensureCompanionWritingSourceReady() {
        return ensureCompanionIndependentApiReady();
    }

    async function callCompanionIndependentApi(prompt, { responseLength = null, systemPrompt = '', jsonMode = false, generationType = 'quiet', finalInstruction = '' } = {}) {
        await ensureCompanionIndependentApiReady();
        if (stateRuntime.companionGeneration) throw new Error('Yêu cầu API riêng trước của Bảy điều hậu trường vẫn đang kết thúc ở nền, hãy đợi nó xong hẳn rồi thử lại');
        const configured = Number(responseLength ?? stateRuntime.serverConfig?.companion?.maxTokens ?? 7000);
        const scopedSystem = [String(systemPrompt || '').trim(), String(finalInstruction || '').trim()].filter(Boolean).join('\n\n');
        const body = {
            prompt: String(prompt || '').trim(),
            systemPrompt: scopedSystem,
            jsonMode: Boolean(jsonMode),
            maxTokens: Math.max(512, Math.min(100000, Number.isFinite(configured) ? configured : 7000)),
            promptPipeline: {
                source: SOURCE_POLICY,
                generationType: String(generationType || 'quiet'),
                fullChatIncluded: false,
                characterCardIncluded: false,
                personaIncluded: false,
                worldBookIncluded: false,
                presetIncluded: false,
                finalInstructionAppended: Boolean(finalInstruction),
            },
        };
        const task = serverFetch('/companion/generate', { method:'POST', body:JSON.stringify(body) });
        stateRuntime.companionGeneration = task;
        try { return await task; }
        finally {
            if (stateRuntime.companionGeneration === task) stateRuntime.companionGeneration = null;
        }
    }

    async function callCompanionJsonWithRecovery(prompt, options = {}) {
        return callCompanionIndependentApi(prompt, options);
    }

    async function runCompanionIndependentApi({ prompt, systemPrompt = '', jsonMode = true, record = null, generationType = 'quiet', finalInstruction = '', writingSource = 'configured' } = {}) {
        const scope = captureChatScope();
        const generation = stateRuntime.dataGeneration;
        const stateAtStart = stateRuntime.state;
        const finalPrompt = jsonMode
            ? `${prompt}\n\n【YÊU CẦU CỨNG VỀ ĐẦU RA】Chỉ xuất đúng một object JSON mà JSON.parse đọc được ngay; không dùng khối mã Markdown, không giải thích, không viết tiếp chính văn.`
            : prompt;
        const data = await callCompanionJsonWithRecovery(finalPrompt, { systemPrompt, jsonMode, generationType, finalInstruction, progressFloor:Number(record?.floor), source:writingSource });
        if (!chatScopeIsCurrent(scope) || stateRuntime.dataGeneration !== generation || stateRuntime.state !== stateAtStart) {
            throw new Error('Đã đổi cuộc trò chuyện: đã loại bỏ kết quả Bảy điều hậu trường của cuộc cũ');
        }
        const now = Date.now();
        const source = data?.source === 'companion-independent-api' ? data.source : companionPayloadSource();
        const model = compactText(data?.model || stateRuntime.serverConfig?.companion?.model || '', 180);
        const sourceLabel = compactText(data?.sourceLabel || companionWritingSourceLabel(), 180);
        const task = {
            id: `companion-api-${globalThis.crypto?.randomUUID?.() || `${now}-${Math.random().toString(16).slice(2)}`}`,
            status: 'completed',
            progress: 100,
            createdAt: now,
            updatedAt: now,
            result: { text: String(data?.text || '') },
            model: model || sourceLabel,
            provider: compactText(data?.provider || 'companion-independent', 120),
            usage: data?.usage || null,
            promptPipeline: data?.promptPipeline || null,
            companionSource: source,
            companionSourceLabel: sourceLabel,
            error: null,
        };
        if (record) {
            Object.assign(record, {
                id: task.id,
                status: 'completed',
                createdAt: Number(record.createdAt || now),
                updatedAt: now,
                applied: false,
                chatIdentity: scope.chatKey,
                chatAnchor: scope.chatAnchor,
                dataGeneration: generation,
                companionSource: source,
                companionSourceLabel: sourceLabel,
                promptPipeline: data?.promptPipeline || null,
            });
            if (!stateAtStart.summaryJobs.includes(record)) stateAtStart.summaryJobs.push(record);
            pruneTaskRecords();
        }
        return task;
    }

    async function runPluginLlm({ feature = 'companion', prompt, systemPrompt = '', jsonMode = false, record = null, writingSource = 'configured' } = {}) {
        const scope=captureChatScope();
        const generation=stateRuntime.dataGeneration;
        await ensureCompanionWritingSourceReady();
        if(!chatScopeIsCurrent(scope)||stateRuntime.dataGeneration!==generation)throw new Error('Đã đổi cuộc trò chuyện: đã hủy việc ghi Bảy điều hậu trường của cuộc cũ');
        if (feature === 'companion') {
            updateCompanionFallbackProgress(Number(record?.floor), null, `${companionWritingSourceLabel()} đang tạo`, 'Chỉ gửi chính văn hiện tại và một lượng tư liệu ký ức có hạn');
        }
        const generationType = feature === 'companion' ? 'companion-scoped' : 'memory-scoped';
        const finalInstruction = feature === 'companion' ? COMPANION_FINAL_CONTRACT : '';
        const task = await runCompanionIndependentApi({ prompt, systemPrompt, jsonMode, record, generationType, finalInstruction, writingSource });
        if(!chatScopeIsCurrent(scope)||stateRuntime.dataGeneration!==generation){
            throw new Error('Đã đổi cuộc trò chuyện: đã loại bỏ kết quả Bảy điều hậu trường của cuộc cũ');
        }
        return task;
    }

    async function generateCompanionOutputForLatest({ force = false, targetFloor = null, fallbackReason = '', silent = false, fromRetry = false } = {}) {
        if (stateRuntime.companionRunning || !stateRuntime.state?.settings?.autoCompanionOutput) return false;
        const operationScope=captureChatScope();const operationState=stateRuntime.state;
        let entry = null;
        if (hasExplicitFloorTarget(targetFloor)) {
            const message = context()?.chat?.[Number(targetFloor)];
            if (message && !message.is_user && !message.is_system) entry = { index:Number(targetFloor), message };
        } else {
            entry = lastAssistantEntry({ requireUserBefore: true });
        }
        if (!entry) {
            if (force && !silent) toast('Lời mở đầu của thẻ nhân vật sẽ không đọc hay tạo thiết bị liên lạc và Bỉ Gian Tư Văn. Hãy gửi một tin nhắn trước.', 'info');
            return false;
        }
        const { index, message } = entry;
        if (stateRuntime.state.settings.companionSkipGreeting && isGreetingMessage(index, message)) return false;
        const signature = messageSignature(index, message);
        const existing = message?.extra?.vvvTheaterCompanion;
        if (!force && existing?.signature === signature && ['ok','fallback-ok'].includes(String(existing?.parseStatus||''))) { decorateCompanionOutput(index); return true; }
        // Lối vào bình thường gặp lần thử lại đang treo thì không mở thêm tác vụ; riêng retry timer thật thì phải cho qua, nếu không sẽ thành cảnh “trông như đang thử lại mà thực ra mãi mãi 0%”.
        if (!force && !fromRetry && existing?.signature === signature && existing?.parseStatus === 'retrying-seven-api') { decorateCompanionOutput(index); return true; }
        if (!force && !existing && index <= Number(stateRuntime.state.progress.lastCompanionFloor ?? -1)) return false;
        if (!force && index < Number(stateRuntime.state.progress.lastCompanionFloor ?? -1)) return false;
        const taskChatIdentity = getChatKey();
        const taskChatAnchor = currentChatAnchor();
        const operationToken={scope:operationScope,floor:index,at:Date.now()};
        stateRuntime.companionOperationToken=operationToken;stateRuntime.companionRunning=true;
        let companionTaskRecord=null;
        startCompanionProgress(
            index,
            fromRetry ? 'Bảy điều hậu trường đang tự thử lại' : 'Bảy điều hậu trường đang tạo ở nền',
            fallbackReason || (fromRetry ? `Tự thử tiếp sau khi thất bại (tối đa ${companionRetryLimit()} lần)` : companionWritingSourceLabel()),
        );
        try {
            await ensureCompanionWritingSourceReady();
            if(!chatScopeIsCurrent(operationScope)||stateRuntime.state!==operationState)return false;
            const prompt = await companionPrompt(index, message);
            if(!chatScopeIsCurrent(operationScope)||stateRuntime.state!==operationState)return false;
            // Mỗi lần viết lại/thử lại đều là một yêu cầu mới tới nguồn viết đang chọn; kết quả thành công vẫn được chữ ký tầng bảo vệ theo cơ chế Exactly-Once.
            const record = { kind: 'companion', floor: index, signature, force: Boolean(force), fallbackReason: compactText(fallbackReason, 80), retryRevision:Math.max(0,Number(existing?.retryAttempt||0)), companionSource:companionPayloadSource() };
            companionTaskRecord=record;
            let task = await runPluginLlm({
                feature: 'companion',
                prompt,
                systemPrompt: `${FALLEN_WRITER_CONTEXT}
【NHIỆM VỤ BẢY ĐIỀU HẬU TRƯỜNG】Bạn là bộ máy nội dung Bảy điều hậu trường của 0-32. Chỉ dùng chính văn hiện tại, ký ức có hạn, hồ sơ nhân vật đã xác nhận và hiện thực hiện tại do chương trình cung cấp trong yêu cầu này; cấm đọc preset của SillyTavern, sách thế giới của nhân vật, Persona hay kết quả biên dịch của Prompt Manager. Chỉ xuất JSON hợp lệ; không được viết tiếp chính văn; không được quyết định thay user. Thời đại/thế giới/phương tiện liên lạc do máy trạng thái của chương trình khóa lại lần cuối, bạn chỉ được dựa vào đó để tạo nội dung hậu trường như điện thoại, Bỉ Gian Tư Văn, ngoại hình nhân vật, Khoảnh khắc/nhật ký/ngày kỷ niệm, cảnh/lời hẹn/bí mật; không được tự đổi thời đại.`,
                jsonMode: true,
                record,
                writingSource: 'configured',
            });
            if (taskChatIdentity !== getChatKey() || (taskChatAnchor && currentChatAnchor() && taskChatAnchor !== currentChatAnchor())) {
                clearCompanionRetryForFloor(index);
                return false;
            }
            if (messageSignature(index, context()?.chat?.[index]) !== signature) {
                clearCompanionRetryForFloor(index);
                return false;
            }
            task = await repairIncompleteCompanionTask(task,{floor:index,signature,message});
            if(task?.companionSource){record.companionSource=task.companionSource;record.companionSourceLabel=task.companionSourceLabel||record.companionSourceLabel;record.promptPipeline=task.promptPipeline||record.promptPipeline;}
            if (taskChatIdentity !== getChatKey() || (taskChatAnchor && currentChatAnchor() && taskChatAnchor !== currentChatAnchor()) || messageSignature(index, context()?.chat?.[index]) !== signature) {
                clearCompanionRetryForFloor(index);
                return false;
            }
            updateCompanionFallbackProgress(index, 96, 'Bảy điều hậu trường đã trả về, đang phân tích và ghi vào', record.companionSourceLabel||companionWritingSourceLabel());
            const applied = await applyCompletedJob(record, task);
            if (!applied) {
                const status = String(record.status || '');
                if (['stale-chat','discarded-after-reset','stale','skipped'].includes(status)) {
                    clearCompanionRetryForFloor(index);
                    return false;
                }
                throw new Error(record.error || 'Kết quả Bảy điều hậu trường chưa ghi vào thành công');
            }
            clearCompanionRetryForFloor(index);
            const written = context()?.chat?.[index]?.extra?.vvvTheaterCompanion;
            if (written) {
                written.retryAttempt = 0;
                written.retryReason = '';
                written.retryAt = 0;
                written.retryForce = false;
                written.failureKind = '';
                if (fallbackReason) {
                    written.parseStatus='fallback-ok';
                    written.fallbackReason=fallbackReason;
                }
                await saveChatExtras(operationScope);
            }
            decorateCompanionOutput(index);
            if (['phone','worldlife','appearance'].includes(stateRuntime.currentTab)) renderCurrentTab();
            // fixed37: tin WeChat chủ động của bố mẹ chạy bất đồng bộ như một nhịp đời sống riêng; thất bại thì tuyệt đối không kéo sập chính văn/Bảy điều hậu trường hiện tại.
            runLaterForScope(operationScope,220,()=>{void maybeRunParentWechatPulse(index).catch(error=>console.warn('[0-32 · Nhịp WeChat của bố mẹ] Tác vụ bất đồng bộ thất bại',error));});
            return record.status !== 'error' && record.status !== 'skipped' && record.status !== 'stale';
        } catch (error) {
            if(!chatScopeIsCurrent(operationScope)||stateRuntime.state!==operationState)return false;
            if(companionTaskRecord&&isCompanionPayloadSource(error?.companionSource)){
                companionTaskRecord.companionSource=String(error.companionSource);
                companionTaskRecord.companionSourceLabel=compactText(error?.companionSourceLabel||companionTaskRecord.companionSourceLabel,180);
            }
            console.error(`[vvv Sân Khấu Nhỏ] Tạo Bảy điều hậu trường thất bại (${companionTaskRecord?.companionSourceLabel||companionWritingSourceLabel()})`, error);
            if(companionTaskRecord && ['GeneratedJsonFormatError','ModelJsonFormatError','CompanionPayloadIncompleteError','CompanionJsonRecoveryError'].includes(String(error?.name||''))){
                companionTaskRecord.status='quality-rejected';companionTaskRecord.applied=true;
                companionTaskRecord.error=compactText(error.message,500);companionTaskRecord.updatedAt=Date.now();
                await saveState({immediate:true,refresh:false,reason:'companion-json-quality-rejected'});
            }
            if (isPermanentAiRetryError(error)) {
                clearCompanionRetryForFloor(index);
                const current = context()?.chat?.[index];
                if (current) {
                    current.extra = current.extra && typeof current.extra === 'object' ? current.extra : {};
                    const shell = current.extra.vvvTheaterCompanion || emptyCompanionShell(index, signature, 'seven-api-failed', companionTaskRecord?.companionSource || companionPayloadSource());
                    shell.signature = signature;
                    shell.source = companionTaskRecord?.companionSource || companionPayloadSource();
                    shell.parseStatus = 'seven-api-failed';
                    shell.fallbackError = compactText(error.message, 500);
                    shell.failureKind = (String(error?.name||'')==='ProviderPolicyRefusalError'||String(error?.code||'')==='provider-policy-refusal'||isProviderPolicyRefusalText(error?.message))
                        ? 'provider-policy-refusal'
                        : 'permanent-error';
                    shell.retryAttempt = 0;
                    shell.retryReason = '';
                    shell.retryAt = 0;
                    shell.retryForce = false;
                    current.extra.vvvTheaterCompanion = shell;
                    await saveChatExtras(operationScope);
                    decorateCompanionOutput(index);
                }
                if (!silent || fromRetry) toast(`Bảy điều hậu trường dừng tự thử lại: ${error.message}`, 'error');
                return false;
            }
            scheduleCompanionRetry(index, signature, error, { fallbackReason, silent:true, force:Boolean(force) });
            return false;
        } finally {
            if(stateRuntime.companionOperationToken===operationToken){stateRuntime.companionOperationToken=null;stateRuntime.companionRunning=false;}
            if(chatScopeIsCurrent(operationScope))clearCompanionLoading(index);
        }
    }

    // ========================= Thiết bị liên lạc tương tác được =========================
    function phoneContactProfile(name) {
        const key=compactText(name,80); if(!key)return null;
        const rows=(stateRuntime.state.phone?.contactProfiles||[]).filter(row=>compactText(row?.name,80)===key);
        const current=stateRuntime.state?.communicationProfile||{}; const currentKey=current.worldKey||'';
        const originKey=stateRuntime.state?.worldTransit?.origin?.worldKey||'origin-modern';
        // S9.3: khi di chuyển trong cùng một thế giới hiện thực thì ưu tiên liên hệ của thế giới gốc, tránh để local profile cũ chặn mất lượt trả lời mới.
        if(currentWorldMatchesOrigin(current)){
            const originRow=rows.find(r=>r.scope==='origin'&&(!r.homeWorldKey||r.homeWorldKey===originKey));
            if(originRow)return originRow;
        }
        return rows.find(r=>r.availability==='active'&&(!r.homeWorldKey||r.homeWorldKey===currentKey)) || rows.find(r=>r.scope==='origin') || rows.at(-1) || null;
    }

    function phoneContactRemark() {
        // fixed38: tính năng ghi chú trong danh bạ đã ngừng. Ghi chú cũ sẽ được dọn khi nạp trạng thái/làm mới danh bạ.
        return '';
    }

    function phoneContactDisplayName(name) {
        return compactText(name,80);
    }

    function ensurePhoneContactProfile(name, meta = {}) {
        const phone=stateRuntime.state.phone; phone.contactProfiles ||= [];
        const clean=compactText(name,80); if(!clean)return null;
        const home=compactText(meta.homeWorldKey,120);
        const cleanMeta={...meta};delete cleanMeta.remark;
        let row=phone.contactProfiles.find(item=>compactText(item?.name,80)===clean && (!home || compactText(item?.homeWorldKey,120)===home));
        if(!row){row={name:clean,scope:cleanMeta.scope||'local',homeWorldKey:home,availability:cleanMeta.availability||'active',source:cleanMeta.source||'',createdAt:Date.now(),updatedAt:Date.now()};phone.contactProfiles.push(row)}
        else {for(const [k,v] of Object.entries(cleanMeta)){if(v!==undefined&&v!==''&&row[k]!==v)row[k]=v}delete row.remark;row.updatedAt=Date.now()}
        if(!phone.contacts.some(item=>(typeof item==='string'?item:item?.name)===clean))phone.contacts.push({name:clean});
        return row;
    }

    function refreshPhoneContactAvailability() {
        const phone=stateRuntime.state?.phone; if(!phone)return;
        phone.contactProfiles ||= [];
        const cp=stateRuntime.state?.communicationProfile||{}; const currentKey=cp.worldKey||'';
        const originKey=stateRuntime.state?.worldTransit?.origin?.worldKey||'origin-modern';
        // Khi liên hệ cũ thiếu metadata thì chuyển theo diện liên hệ thế giới gốc, tránh việc sau khi xuyên không bạn học cũ vẫn nhắn WeChat theo thời gian thực.
        for(const item of phone.contacts||[]){const name=compactText(typeof item==='string'?item:item?.name,80);if(name&&!phone.contactProfiles.some(r=>compactText(r?.name,80)===name))phone.contactProfiles.push({name,scope:'origin',homeWorldKey:originKey,availability:cp.originReachable?'active':'offline-origin',source:'auto-contact-migration',createdAt:Date.now(),updatedAt:Date.now()})}
        for(const row of phone.contactProfiles){
            const scope=row.scope||'origin'; const home=row.homeWorldKey||(scope==='origin'?originKey:'');
            row.scope=scope; if(!row.homeWorldKey&&home)row.homeWorldKey=home;
            row.availability=scope==='origin'?(cp.originReachable?'active':'offline-origin'):((home&&home===currentKey&&cp.available)?'active':'offline-local');
        }
    }

    function phoneContactNames() {
        // Chỉ hiện những liên hệ hiện còn với tới được trong giao diện WeChat; sau khi xuyên thế giới, liên hệ gốc vẫn nằm trong contactProfiles nhưng bị đánh dấu ngoại tuyến.
        refreshPhoneContactAvailability();
        const names = new Set();
        const phone = stateRuntime.state.phone || {};
        const currentKey=stateRuntime.state?.communicationProfile?.worldKey||'';
        const active=name=>{const p=phoneContactProfile(name);return !p || (p.availability==='active'&&(!p.homeWorldKey||p.homeWorldKey===currentKey||p.scope==='origin'));};
        (phone.contacts || []).forEach(item => {const n=compactText(typeof item === 'string' ? item : item?.name, 80);if(n&&active(n))names.add(n)});
        (phone.threads || []).forEach(item => {const n=compactText(item?.contact,80);if(n&&active(n))names.add(n)});
        return [...names].filter(Boolean).sort((a,b) => a.localeCompare(b, 'vi-VN'));
    }

    // fixed37: danh sách WeChat/chat nhóm sắp xếp theo tin nhắn thật cuối cùng. Ai vừa có tin thì tự nhảy lên đầu đúng như WeChat/QQ thật.
    function phoneThreadLatestActivity(thread) {
        const messages=visiblePhoneThreadMessages(thread?.messages||[]);
        const last=messages.at(-1)||null;
        const stamp=last?Math.max(Number(last?.createdAt||0),Number(last?._eventSeq||0)):0;
        return {last,stamp:Number.isFinite(stamp)?stamp:0};
    }
    function phoneConversationSort(a,b) {
        const delta=Number(b?.stamp||0)-Number(a?.stamp||0);
        if(delta)return delta;
        const aHas=Boolean(a?.last),bHas=Boolean(b?.last);if(aHas!==bHas)return aHas?-1:1;
        return compactText(a?.name,120).localeCompare(compactText(b?.name,120),'vi-VN');
    }

    function ensurePhoneThread(contact) {
        const phone = stateRuntime.state.phone;
        phone.threads ||= [];
        let thread = phone.threads.find(item => item.contact === contact);
        if (!thread) {
            thread = { id: uid('thread'), contact, createdAt: Date.now(), updatedAt: Date.now(), messages: [] };
            phone.threads.push(thread);
        }
        return thread;
    }

    function ensurePhoneGroupThread(groupName, members = [], homeWorldKey = '') {
        const phone = stateRuntime.state.phone;
        phone.groupThreads ||= [];
        const cleanName = compactText(groupName, 120);
        const profile = phoneGroupProfile(cleanName);
        const homeKey = compactText(homeWorldKey || profile?.homeWorldKey || stateRuntime.state?.communicationProfile?.worldKey, 120);
        let thread = phone.groupThreads.find(item => item.groupName === cleanName && (!homeKey || compactText(item?.homeWorldKey,120) === homeKey));
        if (!thread) {
            thread = { id:uid('group-thread'), groupName:cleanName, homeWorldKey:homeKey, members:[], createdAt:Date.now(), updatedAt:Date.now(), messages:[] };
            phone.groupThreads.push(thread);
        } else if (!thread.homeWorldKey && homeKey) thread.homeWorldKey = homeKey;
        const mergedMembers = [...new Set([...(thread.members || []), ...(Array.isArray(members) ? members : [])].map(name => compactText(name,80)).filter(Boolean))].slice(0, 50);
        thread.members = mergedMembers;
        return thread;
    }

    function phoneGroupThread(groupName, homeWorldKey = '') {
        const cleanName=compactText(groupName,120); const currentKey=compactText(homeWorldKey || stateRuntime.state?.communicationProfile?.worldKey,120);
        const rows=(stateRuntime.state.phone?.groupThreads || []).filter(item => item.groupName === cleanName);
        return rows.find(item=>!currentKey || compactText(item?.homeWorldKey,120)===currentKey) || rows.at(-1) || null;
    }

    function normalizeGroupChannelType(value, fallback = '') {
        const raw = compactText(value, 60).toLowerCase();
        if (!raw) return fallback;
        if (['smartphone','wechat','weixin','WeChat','Nhóm WeChat'].includes(raw)) return 'wechat';
        return raw;
    }

    function phoneGroupProfile(groupName) {
        const name = compactText(groupName,120);
        const rows=(stateRuntime.state.phone?.groupProfiles || []).filter(item => compactText(item?.groupName,120) === name);
        const current=stateRuntime.state?.communicationProfile || {};
        const currentKey=current.worldKey || '';
        const originKey=stateRuntime.state?.worldTransit?.origin?.worldKey || 'origin-modern';
        // S9.3: khi chỉ đổi thành phố/quốc gia trong cùng một thế giới hiện thực, bản cũ thỉnh thoảng còn sót lại một local profile.
        // Nếu nhóm cùng tên đã có origin profile thì ưu tiên dùng origin, tránh cảnh “tin người dùng ghi vào luồng local, lượt AI ghi vào luồng origin” làm mất một nửa cuộc trò chuyện.
        if (currentWorldMatchesOrigin(current)) {
            const originRow=rows.find(r=>r.scope==='origin'&&(!r.homeWorldKey||r.homeWorldKey===originKey));
            if(originRow)return originRow;
        }
        return rows.find(r=>r.availability==='active'&&(!r.homeWorldKey||r.homeWorldKey===currentKey))
            || rows.find(r=>r.scope==='origin') || rows.at(-1) || null;
    }

    function phoneAttachmentFingerprint(item) {
        return (item?.attachments||[]).map(att=>`${compactText(att?.kind,40)}:${compactText(att?.description,300)}`).join('|');
    }

    function ensurePhoneHistoryPolicy() {
        const phone=stateRuntime.state?.phone;if(!phone)return {appendOnly:true,version:2,nextSeq:1};
        phone.historyPolicy = phone.historyPolicy && typeof phone.historyPolicy==='object' ? phone.historyPolicy : {};
        phone.historyPolicy.appendOnly=true; phone.historyPolicy.version=2;
        let maxSeq=0;
        const scan=row=>{const n=Number(row?._eventSeq||0);if(Number.isFinite(n)&&n>maxSeq)maxSeq=n;};
        for(const key of ['wechat','wechatGroups','channelGroups','sms','calls','notifications','financeEvents'])for(const row of phone[key]||[])scan(row);
        for(const key of ['threads','groupThreads'])for(const thread of phone[key]||[])for(const row of thread?.messages||[])scan(row);
        const configured=Number(phone.historyPolicy.nextSeq||0);
        phone.historyPolicy.nextSeq=Math.max(Number.isFinite(configured)?configured:0,maxSeq+1,1);
        return phone.historyPolicy;
    }

    function nextPhoneEventSeq() {
        const policy=ensurePhoneHistoryPolicy();
        const seq=Math.max(1,Number(policy.nextSeq||1)); policy.nextSeq=seq+1; return seq;
    }

    function stampPhoneEvent(item,{floor,anchorFloor,sidecarId,eventSeq,createdAt}={}) {
        if(!item||typeof item!=='object')return item;
        if(!Number.isFinite(Number(item._eventSeq))) item._eventSeq=Number.isFinite(Number(eventSeq))?Number(eventSeq):nextPhoneEventSeq();
        if(!Number.isFinite(Number(item.createdAt))) item.createdAt=Number.isFinite(Number(createdAt))?Number(createdAt):Date.now();
        if(!Number.isFinite(Number(item._floor))&&Number.isFinite(Number(floor))) item._floor=Number(floor);
        if(!Number.isFinite(Number(item._anchorFloor))&&Number.isFinite(Number(anchorFloor))) item._anchorFloor=Number(anchorFloor);
        if(!item._sidecarId&&sidecarId)item._sidecarId=sidecarId;
        return item;
    }

    function phoneHistoryLogicalKey(item, groupName='') {
        return [
            compactText(groupName,120), compactText(item?.role,30),
            compactText(item?.sender||item?.author||item?.contact,100),
            compactText(item?.content,1800), compactText(item?.time,80),
            phoneAttachmentFingerprint(item), compactText(item?.pendingId,140)
        ].join('||');
    }

    function samePhoneLogicalMessage(a,b,groupName='') {
        if(!a||!b)return false;
        if(a?.id && b?.id && a.id===b.id)return true;
        if(a?.pendingId && b?.pendingId && a.pendingId===b.pendingId)return true;
        const aSender=compactText(a?.sender||a?.author||a?.contact,100), bSender=compactText(b?.sender||b?.author||b?.contact,100);
        const aContent=compactText(a?.content,1800), bContent=compactText(b?.content,1800);
        const aTime=compactText(a?.time,80), bTime=compactText(b?.time,80);
        const aAtt=phoneAttachmentFingerprint(a), bAtt=phoneAttachmentFingerprint(b);
        if(aSender!==bSender || aContent!==bContent || aAtt!==bAtt)return false;
        // S9.4: khi khôi phục bản sao, không nhân đôi cùng một tin của người dùng chỉ vì _sidecarId khác nhau.
        // Khi có thời gian rõ ràng thì thời gian cũng phải khớp; khi không có thời gian thì chỉ coi là cùng một tin nếu sidecar và tin thủ công là bản sao của nhau.
        if(aTime || bTime) return aTime===bTime;
        return Boolean(a?._sidecarId)!==Boolean(b?._sidecarId) || (a?._sidecarId&&a?._sidecarId===b?._sidecarId);
    }

    function mergePhoneMessageMetadata(target, source) {
        if(!target||!source)return target;
        if(!target._sidecarId && source._sidecarId) target._sidecarId=source._sidecarId;
        if(!Number.isFinite(Number(target._eventSeq)) && Number.isFinite(Number(source._eventSeq))) target._eventSeq=Number(source._eventSeq);
        if(!Number.isFinite(Number(target._recoveryFirstSeenAt)) && Number.isFinite(Number(source._recoveryFirstSeenAt))) target._recoveryFirstSeenAt=Number(source._recoveryFirstSeenAt);
        if(!Number.isFinite(Number(target._recoveryOrdinal)) && Number.isFinite(Number(source._recoveryOrdinal))) target._recoveryOrdinal=Number(source._recoveryOrdinal);
        if(!Number.isFinite(Number(target._recoveryOrderRank)) && Number.isFinite(Number(source._recoveryOrderRank))) target._recoveryOrderRank=Number(source._recoveryOrderRank);
        if(!target._recoverySourceLabel && source._recoverySourceLabel) target._recoverySourceLabel=source._recoverySourceLabel;
        if(!target._chronologyConfidence && source._chronologyConfidence) target._chronologyConfidence=source._chronologyConfidence;
        if(!Number.isFinite(Number(target._floor)) && Number.isFinite(Number(source._floor))) target._floor=Number(source._floor);
        if(!target.pendingId && source.pendingId) target.pendingId=source.pendingId;
        if(!Number.isFinite(Number(target._anchorFloor)) && Number.isFinite(Number(source._anchorFloor))) target._anchorFloor=Number(source._anchorFloor);
        if(!target.time && source.time) target.time=source.time;
        if(!target.sender && source.sender) target.sender=source.sender;
        if((!target.attachments||!target.attachments.length) && source.attachments?.length) target.attachments=clone(source.attachments);
        const tc=Number(target.createdAt||0), sc=Number(source.createdAt||0);
        if(!tc && sc) target.createdAt=sc;
        else if(tc&&sc) target.createdAt=Math.min(tc,sc);
        return target;
    }

    function pushPhoneThreadMessageUnique(thread, item, groupName='') {
        if(!thread||!item)return false;
        thread.messages ||= [];
        const existing=thread.messages.find(row=>samePhoneLogicalMessage(row,item,groupName));
        if(existing){mergePhoneMessageMetadata(existing,item);return false;}
        thread.messages.push(item);
        thread.updatedAt=Math.max(Number(thread.updatedAt||0),Number(item?.createdAt||Date.now()));
        return true;
    }

    function phoneMessageRoleRank(item) {
        if(item?.role==='user')return 0;
        if(item?.role==='system')return 1;
        return 2;
    }

    function normalizePhoneThreadChronology(thread, groupName='') {
        if(!thread||!Array.isArray(thread.messages)||thread.messages.length<2)return false;
        let changed=false;
        // Trước tiên chỉ khử phần trùng “tin gốc thủ công + bản sao sidecar” do S9.3 tự chữa sinh ra;
        // khi cả hai đều đến từ NPC thật/bản ghi thủ công thật thì không khử trùng một cách quyết liệt.
        const kept=[];
        for(const row of thread.messages){
            const dup=kept.find(old=>samePhoneLogicalMessage(old,row,groupName) && (Boolean(old?._sidecarId)!==Boolean(row?._sidecarId) || (old?.pendingId&&old.pendingId===row?.pendingId) || (old?.id&&old.id===row?.id)));
            if(dup){
                const preferManual=Boolean(dup?.pendingId||dup?._interactive||!dup?._sidecarId);
                if(preferManual) mergePhoneMessageMetadata(dup,row);
                else {const idx=kept.indexOf(dup);mergePhoneMessageMetadata(row,dup);kept[idx]=row;}
                changed=true;
            } else kept.push(row);
        }
        if(kept.length!==thread.messages.length){thread.messages=kept;changed=true;}

        // Thông báo “đã gửi” của hệ thống kế thừa tầng của tin người dùng có pendingId liền kề, tránh việc sau khi khôi phục bị trôi lên đầu/xuống cuối.
        const pendingFloor=new Map();
        for(const row of thread.messages)if(row?.pendingId&&Number.isFinite(Number(row?._floor)))pendingFloor.set(row.pendingId,Number(row._floor));
        for(const row of thread.messages)if(row?.pendingId&&!Number.isFinite(Number(row?._floor))&&pendingFloor.has(row.pendingId)){row._floor=pendingFloor.get(row.pendingId);changed=true;}

        const original=thread.messages.map((row,index)=>({row,index}));
        const logicalFloor=row=>{
            const f=Number(row?._floor);if(Number.isFinite(f))return f;
            const anchor=Number(row?._anchorFloor);if(Number.isFinite(anchor))return anchor+0.5;
            return Number.POSITIVE_INFINITY;
        };
        const sorted=original.slice().sort((a,b)=>{
            // U1.4: tin mới được sắp xếp chính xác bằng _eventSeq vĩnh viễn; tin cũ ưu tiên dựa vào tầng cốt truyện/bằng chứng xuất hiện lần đầu trong ảnh chụp lịch sử.
            const as=Number(a.row?._eventSeq||0), bs=Number(b.row?._eventSeq||0);
            if(as&&bs&&as!==bs)return as-bs;
            const aRank=Number(a.row?._recoveryOrderRank), bRank=Number(b.row?._recoveryOrderRank);
            if(Number.isFinite(aRank)&&Number.isFinite(bRank)&&aRank!==bRank)return aRank-bRank;
            const af=logicalFloor(a.row), bf=logicalFloor(b.row);
            if(af!==bf)return af-bf;
            const ar=Number(a.row?._recoveryFirstSeenAt||0), br=Number(b.row?._recoveryFirstSeenAt||0);
            if(ar&&br&&ar!==br)return ar-br;
            const ao=Number(a.row?._recoveryOrdinal); const bo=Number(b.row?._recoveryOrdinal);
            if(Number.isFinite(ao)&&Number.isFinite(bo)&&ao!==bo)return ao-bo;
            if(Number.isFinite(af)&&Number.isFinite(bf)){
                const rr=phoneMessageRoleRank(a.row)-phoneMessageRoleRank(b.row); if(rr)return rr;
            }
            const ac=Number(a.row?.createdAt||0), bc=Number(b.row?.createdAt||0);
            if(ac&&bc&&ac!==bc)return ac-bc;
            if(as&&!bs)return 1;
            if(!as&&bs)return -1;
            return a.index-b.index;
        });
        if(sorted.some((entry,index)=>entry.row!==thread.messages[index])){thread.messages=sorted.map(x=>x.row);changed=true;}
        return changed;
    }

    function normalizeAllPhoneThreadChronology() {
        const phone=stateRuntime.state?.phone;if(!phone)return false;let changed=false;
        for(const thread of phone.threads||[])if(normalizePhoneThreadChronology(thread,''))changed=true;
        for(const thread of phone.groupThreads||[])if(normalizePhoneThreadChronology(thread,thread.groupName||''))changed=true;
        return changed;
    }

    function mergeSameNameGroupThreadsForOrigin(groupName) {
        const phone=stateRuntime.state?.phone; if(!phone)return false;
        const current=stateRuntime.state?.communicationProfile||{};
        if(!currentWorldMatchesOrigin(current))return false;
        const name=compactText(groupName,120); if(!name)return false;
        const originKey=compactText(stateRuntime.state?.worldTransit?.origin?.worldKey||'origin-modern',120);
        const profiles=(phone.groupProfiles||[]).filter(row=>compactText(row?.groupName,120)===name);
        const originProfile=profiles.find(row=>row?.scope==='origin');
        if(!originProfile)return false;
        originProfile.homeWorldKey=originKey; originProfile.availability='active'; originProfile.channelType='wechat';
        const rows=(phone.groupThreads||[]).filter(row=>compactText(row?.groupName,120)===name);
        if(!rows.length)return false;
        let target=rows.find(row=>compactText(row?.homeWorldKey,120)===originKey);
        if(!target){target=rows[0];target.homeWorldKey=originKey;}
        let changed=false;
        for(const row of rows){
            if(row===target)continue;
            for(const msg of row.messages||[])if(pushPhoneThreadMessageUnique(target,{...msg},name))changed=true;
            target.members=[...new Set([...(target.members||[]),...(row.members||[])].map(x=>compactText(x,80)).filter(Boolean))].slice(0,80);
        }
        if(rows.length>1){
            const drop=new Set(rows.filter(row=>row!==target).map(row=>row.id));
            phone.groupThreads=(phone.groupThreads||[]).filter(row=>!drop.has(row.id));
            changed=true;
        }
        if(normalizePhoneThreadChronology(target,name))changed=true;
        return changed;
    }

    function recoverPhoneHistoryFromCompanionExtras({force=false}={}) {
        const s=stateRuntime.state; const phone=s?.phone; const chat=context()?.chat||[];
        if(!s||!phone||!chat.length)return false;
        const last=([...chat].reverse().find(m=>m?.extra?.vvvTheaterCompanion?.id))?.extra?.vvvTheaterCompanion;
        const stamp=`${getChatKey()}|${chat.length}|${last?.id||''}|${last?.signature||''}`;
        if(!force&&stateRuntime.phoneHistoryRecoveryStamp===stamp)return false;
        stateRuntime.phoneHistoryRecoveryStamp=stamp;
        phone.wechat ||= []; phone.wechatGroups ||= []; phone.channelGroups ||= []; phone.sms ||= []; phone.calls ||= [];
        phone.threads ||= []; phone.groupThreads ||= []; phone.groupProfiles ||= [];
        const userName=compactText(context()?.name1||'{{user}}',80)||'{{user}}';
        const originKey=compactText(s.worldTransit?.origin?.worldKey||'origin-modern',120);
        let changed=false;
        const ledgerHas=(list,item,group='')=>list.some(row=>{
            if(item?.id&&row?.id===item.id)return true;
            if(item?.pendingId&&row?.pendingId===item.pendingId)return true;
            if(group && compactText(row?.groupName,120)!==compactText(group,120))return false;
            const ra=compactText(row?.sender||row?.author||row?.contact,100), ia=compactText(item?.sender||item?.author||item?.contact,100);
            const rc=compactText(row?.content,1800), ic=compactText(item?.content,1800);
            const rt=compactText(row?.time,80), it=compactText(item?.time,80);
            return ra===ia && rc===ic && phoneAttachmentFingerprint(row)===phoneAttachmentFingerprint(item) && ((!rt&&!it)||rt===it);
        });
        chat.forEach((message,floor)=>{
            const payload=message?.extra?.vvvTheaterCompanion; if(!payload?.phone)return;
            const generatedEpoch=Number.isFinite(Date.parse(String(payload.generatedAt||'')))?Date.parse(String(payload.generatedAt||'')):Date.now();
            const p=payload.phone; const setting=payload.setting||s.communicationProfile||{};
            const sameOrigin=currentWorldMatchesOrigin(setting);
            for(const raw of p.wechat||[]){
                const stored={...raw,_sidecarId:raw?._sidecarId||payload.id,_floor:Number(raw?._floor??payload.floor??floor)};
                if(!ledgerHas(phone.wechat,stored)){phone.wechat.push(stored);changed=true;}
                const authorIsUser=stored.author===userName||stored.author==='{{user}}';
                const other=compactText(authorIsUser?stored.contact:stored.author||stored.contact,100); if(!other)continue;
                const thread=ensurePhoneThread(other);
                if(pushPhoneThreadMessageUnique(thread,{id:uid(authorIsUser?'phone-user-recover':'phone-ai-recover'),role:authorIsUser?'user':'character',sender:authorIsUser?userName:other,content:stored.content||'',attachments:stored.attachments||[],time:stored.time||'',createdAt:Number(stored.createdAt||generatedEpoch),_sidecarId:stored._sidecarId,_floor:stored._floor,pendingId:stored.pendingId||''}))changed=true;
            }
            for(const raw of p.wechatGroups||[]){
                const name=compactText(raw?.groupName,120); if(!name)continue;
                const stored={...raw,_sidecarId:raw?._sidecarId||payload.id,_floor:Number(raw?._floor??payload.floor??floor)};
                if(!ledgerHas(phone.wechatGroups,stored,name)){phone.wechatGroups.push(stored);changed=true;}
                let gp=(phone.groupProfiles||[]).find(row=>compactText(row?.groupName,120)===name&&(sameOrigin?row?.scope==='origin':compactText(row?.homeWorldKey,120)===compactText(setting.worldKey,120)));
                const homeKey=sameOrigin?originKey:compactText(gp?.homeWorldKey||setting.worldKey||s.communicationProfile?.worldKey,120);
                if(!gp){gp={id:uid('group-profile-recover'),groupName:name,type:'other',members:[...(stored.members||[])],topic:'',activityLevel:'medium',source:'companion-extra-recovery',scope:sameOrigin?'origin':'local',homeWorldKey:homeKey,channelType:'wechat',availability:'active',createdAt:Date.now(),updatedAt:Date.now(),_floor:stored._floor};phone.groupProfiles.push(gp);changed=true;}
                else {gp.members=[...new Set([...(gp.members||[]),...(stored.members||[]),stored.sender].map(x=>compactText(x,80)).filter(Boolean))].slice(0,80);if(sameOrigin){gp.scope='origin';gp.homeWorldKey=originKey;gp.channelType='wechat';gp.availability='active';}}
                const thread=ensurePhoneGroupThread(name,stored.members||[],homeKey);
                const senderIsUser=stored.sender===userName||stored.sender==='{{user}}';
                if(pushPhoneThreadMessageUnique(thread,{id:uid(senderIsUser?'group-user-recover':'group-ai-recover'),role:senderIsUser?'user':'character',sender:stored.sender||'Thành viên nhóm',content:stored.content||'',attachments:stored.attachments||[],time:stored.time||'',createdAt:Number(stored.createdAt||generatedEpoch),mentionsUser:Boolean(stored.mentionsUser),_sidecarId:stored._sidecarId,_floor:stored._floor,pendingId:stored.pendingId||''},name))changed=true;
            }
            for(const raw of p.channelGroups||[]){
                const name=compactText(raw?.groupName,120); if(!name)continue;
                const stored={...raw,_sidecarId:raw?._sidecarId||payload.id,_floor:Number(raw?._floor??payload.floor??floor)};
                if(!ledgerHas(phone.channelGroups,stored,name)){phone.channelGroups.push(stored);changed=true;}
            }
            for(const key of ['sms','calls'])for(const raw of p[key]||[]){
                const stored={...raw,_sidecarId:raw?._sidecarId||payload.id,_floor:Number(raw?._floor??payload.floor??floor)};
                if(key==='sms'&&isWechatPaymentSms(stored)){
                    const migrated={...stored,id:stored.id||uid('wechat-pay-recover'),author:'WeChat Pay',category:'payment',_migratedFromSms:true};
                    if(!ledgerHas(phone.wechat,migrated)){phone.wechat.push(migrated);changed=true;}
                    const payThread=ensurePhoneThread('WeChat Pay');
                    if(pushPhoneThreadMessageUnique(payThread,{id:migrated.id,role:'character',sender:'WeChat Pay',content:migrated.content||migrated.smsText||'',time:migrated.time||'',createdAt:Number(migrated.createdAt||generatedEpoch),_sidecarId:migrated._sidecarId,_floor:migrated._floor}))changed=true;
                    continue;
                }
                if(!ledgerHas(phone[key],stored)){phone[key].push(stored);changed=true;}
            }
        });
        if(currentWorldMatchesOrigin(s.communicationProfile||{})){
            const originNames=[...new Set((phone.groupProfiles||[]).filter(row=>row?.scope==='origin').map(row=>compactText(row?.groupName,120)).filter(Boolean))];
            for(const name of originNames)if(mergeSameNameGroupThreadsForOrigin(name))changed=true;
        }
        if(normalizeAllPhoneThreadChronology())changed=true;
        if(changed){
            // S9.4: hội thoại điện thoại vĩnh viễn theo kiểu append-only, không cắt tin cũ vì ngưỡng dung lượng thông thường nữa.
            clearTimeout(stateRuntime.phoneHistoryRecoverySaveTimer);
            const scope=captureChatScope(), operationState=stateRuntime.state;
            stateRuntime.phoneHistoryRecoverySaveTimer=runLaterForScope(scope,120,()=>{
                if(stateRuntime.state===operationState)return saveState({refresh:false,reason:'phone-history-reconcile'});
            });
            console.info('[vvv Sân Khấu Nhỏ] S9.4 đã bù lại các hội thoại điện thoại bị thiếu từ hồ sơ Bảy điều hậu trường của chính văn, đồng thời sửa thứ tự khôi phục/bản sao trùng');
        }
        return changed;
    }

    function mergePhoneRecoveryLedger(target, rows, groupKey='') {
        let added=0; target ||= [];
        for(const raw of rows||[]){
            if(!raw||typeof raw!=='object')continue;
            const group=groupKey?compactText(raw?.groupName,120):'';
            const exists=target.some(old=>{
                if(raw?.id&&old?.id===raw.id)return true;
                if(raw?.pendingId&&old?.pendingId===raw.pendingId)return true;
                if(groupKey&&compactText(old?.groupName,120)!==group)return false;
                return compactText(old?.sender||old?.author||old?.contact,100)===compactText(raw?.sender||raw?.author||raw?.contact,100)
                    && compactText(old?.content,1800)===compactText(raw?.content,1800)
                    && compactText(old?.time,80)===compactText(raw?.time,80)
                    && phoneAttachmentFingerprint(old)===phoneAttachmentFingerprint(raw);
            });
            if(!exists){target.push(clone(raw));added++;}
        }
        return added;
    }

    function mergePhoneRecoveryThreads(targetThreads, sourceThreads, isGroup=false) {
        let added=0;
        for(const src of sourceThreads||[]){
            if(!src||typeof src!=='object')continue;
            const name=compactText(isGroup?src.groupName:src.contact,isGroup?120:100);if(!name)continue;
            let target=isGroup
                ? (targetThreads||[]).find(t=>compactText(t?.groupName,120)===name && (!src.homeWorldKey||!t.homeWorldKey||compactText(t.homeWorldKey,120)===compactText(src.homeWorldKey,120)))
                : (targetThreads||[]).find(t=>compactText(t?.contact,100)===name);
            if(!target){
                target=isGroup?{id:uid('group-thread-recovered'),groupName:name,homeWorldKey:src.homeWorldKey||'',members:clone(src.members||[]),createdAt:src.createdAt||Date.now(),updatedAt:src.updatedAt||Date.now(),messages:[]}
                              :{id:uid('thread-recovered'),contact:name,createdAt:src.createdAt||Date.now(),updatedAt:src.updatedAt||Date.now(),messages:[]};
                targetThreads.push(target);
            }
            if(isGroup)target.members=[...new Set([...(target.members||[]),...(src.members||[])].map(x=>compactText(x,80)).filter(Boolean))].slice(0,100);
            for(const msg of src.messages||[]){
                const before=(target.messages||[]).length;
                pushPhoneThreadMessageUnique(target,clone(msg),isGroup?name:'');
                if((target.messages||[]).length>before)added++;
            }
            normalizePhoneThreadChronology(target,isGroup?name:'');
        }
        return added;
    }
    async function recoverPhoneHistoryFromServerArchive({force=false,silent=true}={}) {
        if(!stateRuntime.state)return 0;
        const scope=captureChatScope();const capturedState=stateRuntime.state;
        const token={scope,at:Date.now()};
        stateRuntime.phoneServerRecoveryToken=token;stateRuntime.phoneServerRecoveryRunning=true;
        try{
            const binding=scope.binding?.archiveId ? scope.binding : (await resolvePermanentArchiveForScope(scope,{create:false}))?.binding;
            if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)return 0;
            const chatKey=scope.serverChatKey;
            if(!binding?.archiveId||!binding?.characterKey||!chatKey)return 0;
            const data=await serverFetch('/archives/phone-history-recovery',{method:'POST',body:JSON.stringify({characterKey:binding.characterKey,archiveId:binding.archiveId,chatKey})});
            if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)return 0;
            const stamp=`${binding.archiveId}|${data?.latestAt||0}|${data?.sourceCount||0}|${data?.messageCount||0}`;
            if(!force&&stamp===stateRuntime.phoneServerRecoveryStamp)return 0;
            stateRuntime.phoneServerRecoveryStamp=stamp;
            const incoming=data?.phone||{};const phone=capturedState.phone;let added=0;
            phone.wechat||=[];phone.wechatGroups||=[];phone.channelGroups||=[];phone.sms||=[];phone.calls||=[];phone.threads||=[];phone.groupThreads||=[];phone.groupProfiles||=[];phone.contacts||=[];phone.contactProfiles||=[];
            added+=mergePhoneRecoveryLedger(phone.wechat,incoming.wechat||[]);
            added+=mergePhoneRecoveryLedger(phone.wechatGroups,incoming.wechatGroups||[],'group');
            added+=mergePhoneRecoveryLedger(phone.channelGroups,incoming.channelGroups||[],'group');
            added+=mergePhoneRecoveryLedger(phone.sms,incoming.sms||[]);
            added+=mergePhoneRecoveryLedger(phone.calls,incoming.calls||[]);
            added+=mergePhoneRecoveryThreads(phone.threads,incoming.threads||[],false);
            added+=mergePhoneRecoveryThreads(phone.groupThreads,incoming.groupThreads||[],true);
            for(const p of incoming.groupProfiles||[]){
                const name=compactText(p?.groupName,120);if(!name)continue;
                let old=phone.groupProfiles.find(r=>compactText(r?.groupName,120)===name&&compactText(r?.homeWorldKey,120)===compactText(p?.homeWorldKey,120));
                if(!old){phone.groupProfiles.push(clone(p));added++;}
                else old.members=[...new Set([...(old.members||[]),...(p.members||[])].map(x=>compactText(x,80)).filter(Boolean))].slice(0,100);
            }
            for(const c of incoming.contacts||[]){const name=compactText(typeof c==='string'?c:c?.name,80);if(name&&!phone.contacts.some(x=>compactText(typeof x==='string'?x:x?.name,80)===name)){phone.contacts.push(clone(c));added++;}}
            for(const c of incoming.contactProfiles||[]){const name=compactText(c?.name,80);if(name&&!phone.contactProfiles.some(x=>compactText(x?.name,80)===name)){phone.contactProfiles.push(clone(c));added++;}}
            if(currentWorldMatchesOrigin(capturedState?.communicationProfile||{})){
                const names=[...new Set((phone.groupProfiles||[]).filter(r=>r?.scope==='origin').map(r=>compactText(r?.groupName,120)).filter(Boolean))];
                for(const name of names)mergeSameNameGroupThreadsForOrigin(name);
            }
            normalizeAllPhoneThreadChronology();
            if(added>0){
                if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)return 0;
                await saveState({immediate:true,refresh:false,reason:'phone-history-server-salvage',forceSnapshot:true});
                if(!chatScopeIsCurrent(scope))return added;
                if(!silent)toast(`📱 Đã lấy lại ${added} mục lịch sử điện thoại từ kho lưu vĩnh viễn/ảnh chụp an toàn`,'success');
                console.info(`[0-32·S10] Đã lấy lại ${added} bản ghi điện thoại từ hầm lưu trữ lịch sử trên máy chủ; chỉ thêm, không xóa`);
            }
            return added;
        }catch(error){
            if(chatScopeIsCurrent(scope))console.warn('[0-32·S10] Cứu lịch sử điện thoại từ máy chủ thất bại',error);
            return 0;
        }finally{
            if(stateRuntime.phoneServerRecoveryToken===token){stateRuntime.phoneServerRecoveryToken=null;stateRuntime.phoneServerRecoveryRunning=false;}
        }
    }

    function phoneChronologyLooseFingerprint(item, threadName='', scope='direct') {
        return [
            compactText(scope,30), compactText(threadName,120),
            compactText(item?.sender||item?.author||item?.contact,100),
            compactText(item?.content||item?.text||item?.message,1800), compactText(item?.time,80),
            phoneAttachmentFingerprint(item),
        ].join('||');
    }

    function currentChatPhoneChronologyEvidence() {
        const rows=[];const chat=context()?.chat||[];const userName=compactText(context()?.name1||'{{user}}',80)||'{{user}}';
        const push=(raw,{scope='direct',threadName='',channel='',floor=-1,sidecarId='',sourceCreatedAt=0,sourceOrdinal=0}={})=>{
            if(!raw||typeof raw!=='object'||!threadName)return;
            const sender=compactText(raw.sender||raw.author||raw.contact,100);
            const normalized={...raw,sender,content:raw.content||raw.text||raw.message||'',_floor:Number.isFinite(Number(raw._floor))?Number(raw._floor):floor,_sidecarId:raw._sidecarId||sidecarId};
            rows.push({
                scope,threadName,channel,fingerprint:phoneChronologyLooseFingerprint(normalized,threadName,scope),
                id:compactText(raw.id,160),pendingId:compactText(raw.pendingId,160),sidecarId:compactText(normalized._sidecarId,160),
                sender:normalized.sender,content:normalized.content,time:compactText(raw.time,80),
                floor:Number.isFinite(Number(normalized._floor))?Number(normalized._floor):null,
                anchorFloor:Number.isFinite(Number(raw._anchorFloor))?Number(raw._anchorFloor):null,
                createdAt:Number.isFinite(Number(raw.createdAt))?Number(raw.createdAt):null,
                eventSeq:Number.isFinite(Number(raw._eventSeq))?Number(raw._eventSeq):null,
                sourceCreatedAt:Number(sourceCreatedAt||0),sourceLabel:`chat-sidecar:${floor}:${sidecarId}`,sourcePriority:-1,sourceOrdinal:Number(sourceOrdinal||0),
            });
        };
        chat.forEach((message,floor)=>{
            const payload=message?.extra?.vvvTheaterCompanion;if(!payload?.phone)return;
            const sourceAt=Number.isFinite(Date.parse(String(payload.generatedAt||'')))?Date.parse(String(payload.generatedAt)):Number(message?.send_date||0)||Date.now();
            (payload.phone.wechatGroups||[]).forEach((raw,i)=>{const name=compactText(raw?.groupName,120);if(name)push(raw,{scope:'group',threadName:name,channel:'wechatGroups',floor,sidecarId:payload.id,sourceCreatedAt:sourceAt,sourceOrdinal:i});});
            (payload.phone.channelGroups||[]).forEach((raw,i)=>{const name=compactText(raw?.groupName,120);if(name)push(raw,{scope:'group',threadName:name,channel:'channelGroups',floor,sidecarId:payload.id,sourceCreatedAt:sourceAt,sourceOrdinal:i});});
            (payload.phone.wechat||[]).forEach((raw,i)=>{
                const author=compactText(raw?.author,100),contact=compactText(raw?.contact,100);
                const name=(author===userName||author==='{{user}}')?contact:author;if(name)push({...raw,sender:(author===userName||author==='{{user}}')?userName:name},{scope:'direct',threadName:name,channel:'wechat',floor,sidecarId:payload.id,sourceCreatedAt:sourceAt,sourceOrdinal:i});
            });
            (payload.phone.sms||[]).forEach((raw,i)=>{
                const author=compactText(raw?.author,100),contact=compactText(raw?.contact,100);
                const name=(author===userName||author==='{{user}}')?contact:author;if(name)push({...raw,sender:(author===userName||author==='{{user}}')?userName:name},{scope:'direct',threadName:name,channel:'sms',floor,sidecarId:payload.id,sourceCreatedAt:sourceAt,sourceOrdinal:i});
            });
        });
        return rows;
    }

    function buildPhoneChronologyEvidenceMaps(rows=[]) {
        const sorted=[...(rows||[])].filter(Boolean).sort((a,b)=>Number(a.sourceCreatedAt||0)-Number(b.sourceCreatedAt||0)||Number(a.sourcePriority??1)-Number(b.sourcePriority??1)||Number(a.sourceOrdinal||0)-Number(b.sourceOrdinal||0));
        const maps={id:new Map(),pending:new Map(),sidecar:new Map(),fingerprint:new Map()};
        const put=(map,key,row)=>{if(key&&!map.has(key))map.set(key,row);};
        sorted.forEach((row,rank)=>{
            row={...row,_rank:rank};
            put(maps.id,compactText(row.id,180),row);
            put(maps.pending,compactText(row.pendingId,180),row);
            const side=compactText(row.sidecarId,160);if(side)put(maps.sidecar,[side,compactText(row.sender,100),compactText(row.content,1800),compactText(row.time,80)].join('||'),row);
            put(maps.fingerprint,compactText(row.fingerprint,4000),row);
        });
        return maps;
    }

    function matchPhoneChronologyEvidence(message,threadName,scope,maps) {
        const id=compactText(message?.id,180);if(id&&maps.id.has(id))return {row:maps.id.get(id),type:'id'};
        const pending=compactText(message?.pendingId,180);if(pending&&maps.pending.has(pending))return {row:maps.pending.get(pending),type:'pending'};
        const side=compactText(message?._sidecarId,160);if(side){const k=[side,compactText(message?.sender||message?.author||message?.contact,100),compactText(message?.content,1800),compactText(message?.time,80)].join('||');if(maps.sidecar.has(k))return {row:maps.sidecar.get(k),type:'sidecar'};}
        const fp=phoneChronologyLooseFingerprint(message,threadName,scope);if(maps.fingerprint.has(fp))return {row:maps.fingerprint.get(fp),type:'history'};
        return null;
    }

    function enrichThreadChronology(thread,threadName,scope,maps,{apply=false}={}) {
        const target=apply?thread:{...thread,messages:clone(thread?.messages||[])};target.messages||=[];
        const before=target.messages.map((m,i)=>compactText(m?.id,160)||`${phoneHistoryLogicalKey(m,threadName)}#${i}`);
        const stats={exact:0,strong:0,unresolved:0,enriched:0,moved:0,total:target.messages.length};
        for(const message of target.messages){
            const matched=matchPhoneChronologyEvidence(message,threadName,scope,maps);
            if(!matched){stats.unresolved++;continue;}
            const e=matched.row;const hadEvidence=Number.isFinite(Number(message._recoveryOrderRank));
            if(!Number.isFinite(Number(message._floor))&&Number.isFinite(Number(e.floor)))message._floor=Number(e.floor);
            if(!Number.isFinite(Number(message._anchorFloor))&&Number.isFinite(Number(e.anchorFloor)))message._anchorFloor=Number(e.anchorFloor);
            if(!message._sidecarId&&e.sidecarId)message._sidecarId=e.sidecarId;
            if(!message.pendingId&&e.pendingId)message.pendingId=e.pendingId;
            if(!Number.isFinite(Number(message.createdAt))&&Number.isFinite(Number(e.createdAt)))message.createdAt=Number(e.createdAt);
            if(!Number.isFinite(Number(message._eventSeq))&&Number.isFinite(Number(e.eventSeq)))message._eventSeq=Number(e.eventSeq);
            message._recoveryFirstSeenAt=Number(e.sourceCreatedAt||0)||message._recoveryFirstSeenAt||0;
            message._recoveryOrdinal=Number(e.sourceOrdinal||0);
            message._recoveryOrderRank=Number(e._rank||0);
            message._recoverySourceLabel=compactText(e.sourceLabel,260);
            message._chronologyConfidence=(matched.type==='id'||matched.type==='pending'||matched.type==='sidecar'||Number.isFinite(Number(e.floor)))?'exact':'strong';
            stats[message._chronologyConfidence]++;
            if(!hadEvidence)stats.enriched++;
        }
        normalizePhoneThreadChronology(target,scope==='group'?threadName:'');
        const after=target.messages.map((m,i)=>compactText(m?.id,160)||`${phoneHistoryLogicalKey(m,threadName)}#${i}`);
        stats.moved=after.reduce((n,key,i)=>n+(key!==before[i]?1:0),0);
        return {target,stats};
    }
    async function precisePhoneChronology({apply=false,silent=false}={}) {
        if(!stateRuntime.state?.phone)throw new Error('Dữ liệu điện thoại chưa được khởi tạo');
        const scope=captureChatScope();const capturedState=stateRuntime.state;
        // U1.7: bản xem trước hoàn toàn chỉ đọc; apply cũng gắn với chat scope bất biến, đổi cuộc trò chuyện là dừng ngay, tuyệt đối không đem bằng chứng của cuộc A áp vào cuộc B.
        if(apply){await recoverPhoneHistoryFromServerArchive({force:true,silent:true});if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)throw new Error('Đã đổi cuộc trò chuyện, việc đưa điện thoại về chỗ đã hủy an toàn');}
        const binding=scope.binding?.archiveId ? scope.binding : (await resolvePermanentArchiveForScope(scope,{create:false}))?.binding;
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)throw new Error('Đã đổi cuộc trò chuyện, việc đưa điện thoại về chỗ đã hủy an toàn');
        const chatKey=scope.serverChatKey;if(!binding?.archiveId||!binding?.characterKey||!chatKey)throw new Error('Cuộc trò chuyện của nhân vật hiện tại chưa gắn với kho lưu vĩnh viễn');
        const data=await serverFetch('/archives/phone-chronology-evidence',{method:'POST',body:JSON.stringify({characterKey:binding.characterKey,archiveId:binding.archiveId,chatKey})});
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==capturedState)throw new Error('Đã đổi cuộc trò chuyện, kết quả đưa điện thoại về chỗ chưa được áp dụng');
        const evidence=[...(data?.evidence||[]),...currentChatPhoneChronologyEvidence()];
        const maps=buildPhoneChronologyEvidenceMaps(evidence);
        const phone=capturedState.phone;const totals={threads:0,messages:0,exact:0,strong:0,unresolved:0,enriched:0,moved:0,sources:Number(data?.sourceCount||0),evidence:evidence.length};
        const process=(thread,name,scopeName)=>{const result=enrichThreadChronology(thread,name,scopeName,maps,{apply});totals.threads++;for(const k of ['total','exact','strong','unresolved','enriched','moved']){const dst=k==='total'?'messages':k;totals[dst]+=Number(result.stats[k]||0);}return result;};
        for(const thread of phone.threads||[])process(thread,compactText(thread?.contact,100),'direct');
        for(const thread of phone.groupThreads||[])process(thread,compactText(thread?.groupName,120),'group');
        if(apply){
            ensurePhoneHistoryPolicy();
            await saveState({immediate:true,refresh:false,reason:'user-phone-chronology-calibration',forceSnapshot:true});
            if(!chatScopeIsCurrent(scope))return totals;
            renderRolePhone();if(stateRuntime.currentTab==='phone')renderCurrentTab();
            if(!silent)toast(`🧭 Đã đưa lịch sử điện thoại về đúng chỗ: ${totals.moved} lần điều chỉnh vị trí, ${totals.exact} bằng chứng chính xác, ${totals.strong} bằng chứng mạnh`,'success');
        }
        return totals;
    }

    function scheduleServerPhoneHistoryRecovery(delay=80) {
        clearTimeout(stateRuntime.phoneServerRecoveryTimer);
        const scope=captureChatScope();
        stateRuntime.phoneServerRecoveryTimer=runLaterForScope(scope,Math.max(20,delay),async()=>{
            const added=await recoverPhoneHistoryFromServerArchive({silent:true});
            if(!chatScopeIsCurrent(scope)||added<=0)return;
            const phoneOpen=!document.getElementById('vvvtm-role-phone')?.hidden;
            const activeConversation=phoneOpen && ((stateRuntime.phoneView==='wechat'&&Boolean(stateRuntime.phoneSelectedContact)) || (stateRuntime.phoneView==='channels'&&Boolean(stateRuntime.phoneSelectedContact)));
            if(!activeConversation) renderRolePhone();
            if(stateRuntime.currentTab==='phone' && !activeConversation) renderCurrentTab();
        });
    }

    // R9S1P31: coi “tin nhắn nhóm WeChat đã tồn tại” là bằng chứng mạnh cho việc nhóm chat có thật, và tự sửa trạng thái cũ.
    // P30 chỉ khôi phục active/offline cho những groupProfiles đã có; nếu profile trong bản lưu cũ vốn đã thiếu, scope/homeWorldKey
    // lệch chỗ, hoặc channelType vẫn là giá trị cũ smartphone thì danh sách vẫn có thể hiện 0 nhóm chat.
    // Hàm này chỉ sắp xếp trạng thái tại chỗ, không gọi API và cũng không xóa bất kỳ tin nhắn lịch sử nào.
    function reconcileWechatGroupState() {
        const s = stateRuntime.state;
        const phone = s?.phone;
        if (!phone) return false;
        phone.groupProfiles ||= [];
        phone.groupThreads ||= [];
        phone.wechatGroups ||= [];
        const cp = s.communicationProfile || {};
        const currentKey = compactText(cp.worldKey,120);
        const originKey = compactText(s.worldTransit?.origin?.worldKey || 'origin-modern',120);
        const originOnline = Boolean(cp.originReachable);
        const currentWechat = cp.communicationType === 'smartphone' && cp.available !== false;
        let changed = false;

        // Tương thích dữ liệu cũ trước: smartphone / WeChat / weixin đều quy về wechat.
        for (const row of phone.groupProfiles) {
            if (!row || typeof row !== 'object') continue;
            const normalized = normalizeGroupChannelType(row.channelType, row.channelType ? '' : (currentWechat ? 'wechat' : ''));
            if (normalized && row.channelType !== normalized) { row.channelType = normalized; changed = true; }
        }

        for (const msg of phone.wechatGroups) {
            const name = compactText(msg?.groupName,120);
            if (!name) continue;
            const hintedHome = compactText(msg?._homeWorldKey,120);
            let rows = phone.groupProfiles.filter(row => compactText(row?.groupName,120) === name);
            let profile = hintedHome ? rows.find(row => compactText(row?.homeWorldKey,120) === hintedHome) : null;
            profile ||= rows.find(row => row?.availability === 'active' && normalizeGroupChannelType(row?.channelType,'wechat') === 'wechat');
            profile ||= originOnline ? rows.find(row => row?.scope === 'origin') : rows.find(row => row?.scope !== 'origin' && (!row?.homeWorldKey || row.homeWorldKey === currentKey));
            profile ||= rows.at(-1) || null;

            if (!profile) {
                const scope = originOnline ? 'origin' : 'local';
                const homeWorldKey = hintedHome || (scope === 'origin' ? originKey : currentKey);
                profile = {
                    id:uid('group-profile'), groupName:name, type:'other', members:[], topic:'', activityLevel:'medium',
                    source:'wechat-history-reconcile', scope, homeWorldKey, channelType:'wechat',
                    availability:scope === 'origin' ? (originOnline ? 'active' : 'offline-origin') : (currentWechat ? 'active' : 'offline-local'),
                    createdAt:Date.now(), updatedAt:Date.now(), _floor:Number(msg?._floor ?? -1),
                };
                phone.groupProfiles.push(profile); changed = true;
            }

            if (normalizeGroupChannelType(profile.channelType,'wechat') !== profile.channelType) { profile.channelType='wechat'; changed=true; }
            const mergedMembers=[...new Set([...(profile.members||[]), ...(msg?.members||[]), msg?.sender].map(x=>compactText(x,80)).filter(Boolean))].slice(0,50);
            if (mergedMembers.length !== (profile.members||[]).length) { profile.members=mergedMembers; changed=true; }

            // Chỉ thế giới thật sự dùng được WeChat mới khôi phục nhóm tương ứng về active; quan hệ ngoại tuyến xuyên thế giới vẫn giữ ngoại tuyến.
            if (profile.scope === 'origin' && originOnline && profile.availability !== 'active') { profile.availability='active'; changed=true; }
            if (profile.scope !== 'origin' && currentWechat && (!profile.homeWorldKey || !currentKey || profile.homeWorldKey === currentKey) && profile.availability !== 'active') { profile.availability='active'; changed=true; }

            const threadHome = compactText(profile.homeWorldKey || hintedHome || (profile.scope === 'origin' ? originKey : currentKey),120);
            const thread = ensurePhoneGroupThread(name, mergedMembers, threadHome);
            if (thread && !(thread.messages||[]).some(row => row._sidecarId && row._sidecarId === msg?._sidecarId || (!row._sidecarId && compactText(row?.sender,100)===compactText(msg?.sender,100) && compactText(row?.content,1800)===compactText(msg?.content,1800)))) {
                const userName = compactText(context()?.name1 || '{{user}}',120) || '{{user}}';
                const senderIsUser = msg?.sender === userName || msg?.sender === '{{user}}';
                thread.messages.push({
                    id:uid(senderIsUser?'group-user-reconcile':'group-ai-reconcile'), role:senderIsUser?'user':'character', sender:msg?.sender || 'Thành viên nhóm',
                    content:msg?.content || '', time:msg?.time || '', createdAt:Date.now(), mentionsUser:Boolean(msg?.mentionsUser),
                    _sidecarId:msg?._sidecarId, _floor:Number(msg?._floor ?? -1),
                });
                thread.updatedAt=Date.now(); changed=true;
            }
        }
        return changed;
    }

    // R9S1P30: khả năng với tới nhóm chat phải khôi phục theo thời gian thực cùng “mạng của thế giới hiện tại/thế giới gốc”, y như với danh bạ.
    // Bản cũ chỉ làm mới contactProfiles chứ không làm mới groupProfiles: sau khi người dùng từ dị giới/tuyến lịch sử quay về thế giới gốc,
    // Liên hệ đã active trở lại, nhưng nhóm chat vẫn có thể kẹt ở offline-origin. Thành ra dưới chính văn thì thấy tin nhóm WeChat mới,
    // mà mở WeChat đầy đủ lại hiện “0 nhóm chat”. Ở đây chỉ sửa trạng thái, không xóa lịch sử và không gọi thêm API.
    function refreshPhoneGroupAvailability() {
        const phone = stateRuntime.state?.phone;
        if (!phone) return;
        phone.groupProfiles ||= [];
        const cp = stateRuntime.state?.communicationProfile || {};
        const currentKey = compactText(cp.worldKey, 120);
        const originKey = compactText(stateRuntime.state?.worldTransit?.origin?.worldKey || 'origin-modern', 120);
        const originOnline = Boolean(cp.originReachable);
        const currentOnline = cp.available !== false && cp.communicationType !== 'none';

        for (const row of phone.groupProfiles) {
            if (!row || typeof row !== 'object') continue;
            const scope = row.scope || 'origin';
            const home = compactText(row.homeWorldKey || (scope === 'origin' ? originKey : currentKey), 120);
            row.scope = scope;
            if (!row.homeWorldKey && home) row.homeWorldKey = home;
            const normalizedChannel = normalizeGroupChannelType(row.channelType, cp.communicationType === 'smartphone' ? 'wechat' : '');
            if (normalizedChannel) row.channelType = normalizedChannel;

            if (scope === 'origin') {
                row.availability = originOnline ? 'active' : 'offline-origin';
            } else {
                row.availability = currentOnline && (!home || !currentKey || home === currentKey) ? 'active' : 'offline-local';
            }
            row.updatedAt = Number(row.updatedAt || Date.now());
        }
    }

    function phoneGroupNames() {
        const names = new Set();
        (stateRuntime.state.phone?.groupProfiles || []).forEach(item => names.add(compactText(item?.groupName, 120)));
        (stateRuntime.state.phone?.groupThreads || []).forEach(item => names.add(compactText(item?.groupName, 120)));
        (stateRuntime.state.phone?.wechatGroups || []).forEach(item => names.add(compactText(item?.groupName, 120)));
        (stateRuntime.state.phone?.channelGroups || []).forEach(item => names.add(compactText(item?.groupName, 120)));
        return [...names].filter(Boolean).sort((a,b) => a.localeCompare(b, 'vi-VN'));
    }

    function phoneClock() {
        const wall = new Date();
        const storyTime=effectiveStoryTime();
        const minutes=sceneClockMinuteValues(storyTime).at(-1);
        const fact=sceneDateFacts(storyTime).at(-1);
        const year=strictGregorianYear(storyTime);
        const time=Number.isFinite(minutes)
            ? `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`
            : wall.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',hour12:false});
        let date=wall.toLocaleDateString('vi-VN',{month:'long',day:'numeric',weekday:'short'});
        if(fact){
            const labelDate=new Date(Number.isFinite(year)?year:wall.getFullYear(),fact.month-1,fact.day);
            const weekday=labelDate.toLocaleDateString('vi-VN',{weekday:'short'});
            date=`${fact.day}/${fact.month} ${weekday}`;
        }
        return {time,date};
    }


