    function s9Hash(text='') { let h=2166136261; for(const ch of String(text)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);} return h>>>0; }
    function s9Pick(arr,seed){ return arr[Math.abs(Number(seed)||0)%arr.length]; }
