    function s9SetCatalogPage(platform,page,totalPages){ stateRuntime.phoneCatalogPage ||= {}; stateRuntime.phoneCatalogPage[platform]=Math.max(1,Math.min(Math.max(1,totalPages||1),Number(page)||1)); }
