        const base=stores?stores[(ordinal+platformOffset)%stores.length]:`${S91_STORE_ROOTS[(ordinal+categoryIndex*3+platformOffset)%S91_STORE_ROOTS.length]}${S92_FOOD_TYPE[cat]||'Quán nhỏ'}`;
