            id:uid('phone-activity'),type:compactText(type,60)||'other',title:compactText(title,180),detail:compactText(detail,900),
            visibility:options.visibility==='friends'?'friends':'co-located-observable',sceneLocation:compactText(options.sceneLocation||stateRuntime.state?.scene?.location||'',180),
            sourceFloor:Number.isFinite(Number(options.floor))?Number(options.floor):Math.max(0,(context()?.chat?.length||1)-1),
