        const storyEvent=(phone.storyLedger||[]).slice().reverse().find(item=>compactText(item?.relatedId,140)===compactText(row.eventId||row.relatedId,140)||compactText(item?.relatedId,140)===compactText(row.relatedId,140));
        if(storyEvent){storyEvent.knownBy=[...new Set([...(storyEvent.knownBy||storyEvent.participants||[]),row.npc])].slice(0,30);const userName=compactText(context()?.name1||'{{user}}',80)||'{{user}}';if(npcNameKey(row.npc)===npcNameKey(userName))storyEvent.userKnows=true;storyEvent.updatedAt=Date.now();}
        const order=row.relatedId?s8AllPhoneOrders().find(item=>item.id===row.relatedId):null;
        if(order){order.awareness ||= {};order.awareness.directlyInformed=[...new Set([...(order.awareness.directlyInformed||[]),row.npc])].slice(0,80);}
        return row;
