        const data={id:stable,title:compactText(title,160),date:compactText(date,80),note:compactText(note,500),source:compactText(source,60),relatedId:compactText(relatedId,140),route:compactText(route,60),dueFloor:Number.isFinite(Number(dueFloor))?Number(dueFloor):-1,time:phoneClock().time,updatedAt:Date.now(),automatic:true};
