    function cleanupLegacyTimeline() {
        const rows=stateRuntime.state?.tables?.mainline||[];
        const seen=new Set();
        const clean=[];
        for(const row of rows){
            const event=compactText(row?.['Tóm tắt sự kiện'],1800);
            if(!event) continue;
            const floor=String(row?.['Tầng']??'').trim();
            const date=String(row?.['Ngày']??'').trim();
            const key=`${floor}|${date}|${event}`;
            if(seen.has(key)) continue;
            seen.add(key);clean.push(row);
        }
        clean.sort((a,b)=>Number(a?.['Tầng']??0)-Number(b?.['Tầng']??0));
        stateRuntime.state.tables.mainline=clean;
    }

    function mergeLegacyTakeoverData(data,start,end,model='',{fullStage=true}={}) {
        const s=stateRuntime.state;
        const memory=data?.memory&&typeof data.memory==='object'?data.memory:data||{};
        const rawMainline=Array.isArray(memory?.mainline)?memory.mainline:[];
        const safeMemory={...memory,mainline:[]};
        mergeCompanionMemory(safeMemory,end);
        for(const item of data?.promises||[])upsertPromiseSnapshot({...item,_takeoverRange:`${start}-${end}`},Number(item.floor??end),`takeover-${start}-${end}`);
        for(const item of data?.secrets||[])upsertSecretSnapshot({...item,_takeoverRange:`${start}-${end}`},Number(item.floor??end),`takeover-${start}-${end}`);
        for(const raw of data?.appearances||[]){const floor=resolvedMemoryFloor(raw?.floor,end);upsertAppearanceSnapshot({...cleanAppearanceSnapshot([raw],floor)[0],aliases:raw.aliases||[],identityRevealed:Boolean(raw.identityRevealed),source:raw.source||'chat'},`takeover-${start}-${end}`,floor);}
        mergeMemoryAnchors(memory?.anchors||data?.anchors,end);

        const candidates=[];
        for(const item of rawMainline){
            const event=compactText(item?.summary??item?.event,1800);if(!event)continue;
            candidates.push({date:item?.date??'',start:item?.start??'',end:item?.end??'',event,floor:resolvedMemoryFloor(item?.floor,end)});
        }
        const timeline=data?.timeline&&typeof data.timeline==='object'?data.timeline:null;
        const timelineEvent=compactText(timeline?.event??timeline?.summary,1800);
        if(timelineEvent)candidates.push({date:timeline?.date??'',start:timeline?.start??'',end:timeline?.end??'',event:timelineEvent,floor:resolvedMemoryFloor(timeline?.floor,end)});
        const summary=compactText(data?.summary,12000);
        if(!candidates.length&&summary)candidates.push({date:'',start:'',end:'',event:summary.split(/\n+/)[0].slice(0,900),floor:end});
        for(const item of candidates){
            uniquePush(s.tables.mainline,{
                'Ngày':item.date,'Giờ bắt đầu':item.start,'Giờ kết thúc':item.end,'Tóm tắt sự kiện':item.event,'Trạng thái':'Đã hoàn thành','Tầng':String(item.floor),
                _sourceFloor:Number(item.floor),_takeoverRange:`${start}-${end}`,_takeoverGenerated:true,
            },row=>`${row['Tầng']}|${row['Tóm tắt sự kiện']}`);
        }
        cleanupLegacyTimeline();

        let summaryRow=null;
        if(fullStage&&summary){
            summaryRow=s.tables.summaries.find(row=>row._takeoverRange===`${start}-${end}`&&row['Loại']==='Tổng kết giai đoạn');
            if(!summaryRow){
                // U1.6.1兼容升级前已经完成的旧接管任务：保留自由文本证据，但绝不把它标成“阶段总结Đã hoàn thành”。
                const structured=normalizeStageSummaryPayload({timeScene:{date:'Chưa xác định',period:'Chưa xác định',location:'Chưa xác định',weatherAtmosphere:'Chưa xác định'},corePlotActions:[{fact:summary,cause:'Tác vụ cũ không cung cấp trường có cấu trúc',result:'Cần đọc lại chính văn để tạo bản theo định dạng cố định',floors:`${start}-${end}`}],peopleRelations:[],secretsKnowledge:[],items:[],promises:[],unresolved:[]},start,end);
                summaryRow={'Loại':'Tổng kết giai đoạn','Trạng thái':'Cần tính lại','Nội dung tổng kết':formatStageSummaryPayload(structured),'Tầng bao phủ':`${start}-${end}`,'Mô hình':model||'Tiếp quản hồ sơ cũ','Thời điểm tạo':nowText(),'Khóa':'Không','Trạng thái ẩn':'Chưa ẩn',_id:uid('takeover-summary'),_takeoverRange:`${start}-${end}`,_history:[],_legacyFreeText:summary,_formatVersion:STAGE_SUMMARY_FORMAT_VERSION,_staleReason:'Tác vụ tiếp quản cũ trước khi nâng cấp là văn bản tự do, không tính vào tiến độ hoàn thành; hãy làm lại đoạn này'};
                s.tables.summaries.push(summaryRow);
            }
        }
        return summaryRow;
    }

    async function unhideEntireCurrentChat(scope=captureChatScope()) {
        if(!chatScopeIsCurrent(scope))return false;
        const chat=context()?.chat||[];if(!chat.length)return true;
        const end=Math.max(0,chat.length-1);const command=`/unhide 0-${end}`;
        try{
            const module=await import('/scripts/slash-commands.js');
            if(!chatScopeIsCurrent(scope))return false;
            if(typeof module.executeSlashCommandsWithOptions!=='function')throw new Error('slash-command-api-missing');
            await module.executeSlashCommandsWithOptions(command,{handleParserErrors:false,handleExecutionErrors:true});
            return chatScopeIsCurrent(scope);
        }catch(slashError){
            if(!chatScopeIsCurrent(scope))return false;
            try{
                const chats=await import('/scripts/chats.js');
                if(!chatScopeIsCurrent(scope))return false;
                if(typeof chats.hideChatMessageRange!=='function')throw slashError;
                await chats.hideChatMessageRange(0,end,true,'');
                return chatScopeIsCurrent(scope);
            }catch(error){console.warn('[vvv Sân Khấu Nhỏ] Khôi phục toàn bộ các tầng bị ẩn thất bại',error);return false;}
        }
    }

    async function clearTheaterMessageExtras(scope=captureChatScope()) {
        if(!chatScopeIsCurrent(scope))return false;
        const chat=context()?.chat||[];let changed=false;
        for(const message of chat){
            if(!message?.extra||typeof message.extra!=='object')continue;
            if(Object.prototype.hasOwnProperty.call(message.extra,'vvvTheaterCompanion')){delete message.extra.vvvTheaterCompanion;changed=true;}
            if(Object.prototype.hasOwnProperty.call(message.extra,'vvvTheaterUi')){delete message.extra.vvvTheaterUi;changed=true;}
        }
        if(!chatScopeIsCurrent(scope))return false;
        document.querySelectorAll('.vvvtm-inline-extra,.vvvtm-inline-loading').forEach(node=>node.remove());
        if(changed){await saveChatExtras(scope);if(!chatScopeIsCurrent(scope))return false;}
        return true;
    }

    function resetTransientRuntimeForWipe(scope=captureChatScope()) {
        if(!chatScopeIsCurrent(scope))return false;
        stateRuntime.dataGeneration+=1;stateRuntime.takeoverAbort=true;stateRuntime.takeoverRunning=false;
        stateRuntime.extracting=false;stateRuntime.extractOperationToken=null;stateRuntime.recentEventRerunFloor=-1;stateRuntime.summaryRunning=false;stateRuntime.summaryOperationToken=null;stateRuntime.memoryCollectionAbort=true;stateRuntime.memoryCollectionRunning=false;stateRuntime.memoryCollectionOperationToken=null;stateRuntime.memoryReviewAbort=true;stateRuntime.memoryReviewRunning=false;stateRuntime.memoryReviewOperationToken=null;stateRuntime.memoryReviewResult=null;stateRuntime.memoryReviewReportClosed=true;stateRuntime.companionRunning=false;stateRuntime.companionOperationToken=null;stateRuntime.duplicateGuardRunning=false;stateRuntime.duplicateGuardToken=null;stateRuntime.mainCompanionProcessing=false;stateRuntime.mainCompanionToken=null;stateRuntime.phoneSending=false;stateRuntime.phoneSendingToken=null;stateRuntime.lifeRescueResumeRunning=false;stateRuntime.lifeRescueResumeToken=null;
        stateRuntime.memoryPipelineNotice='';
        const currentSaveTimer=stateRuntime.saveTimers.get(scope.chatKey);if(currentSaveTimer){clearTimeout(currentSaveTimer);stateRuntime.saveTimers.delete(scope.chatKey);}clearTimeout(stateRuntime.autoTimer);clearTimeout(stateRuntime.companionTimer);clearTimeout(stateRuntime.mainCompanionTimer);clearTimeout(stateRuntime.extractRetryTimer);clearTimeout(stateRuntime.assistantQueueDrainTimer);stateRuntime.assistantQueueDrainTimer=null;
        const archivePending=stateRuntime.permanentArchiveSyncs.get(scope.chatKey);if(archivePending?.timer)clearTimeout(archivePending.timer);stateRuntime.permanentArchiveSyncs.delete(scope.chatKey);
        for(const timer of stateRuntime.companionRetryTimers.values())clearTimeout(timer);
        stateRuntime.companionRetryTimers.clear();stateRuntime.extractRetryTimer=null;stateRuntime.extractRetryAttempt=0;
        for(const timer of stateRuntime.fallbackProgressTimers.values())clearInterval(timer);
        stateRuntime.fallbackProgressTimers.clear();stateRuntime.fallbackProgressValues.clear();stateRuntime.retrievalHits=[];stateRuntime.serverTasks=[];stateRuntime.indexStatus=null;
        return true;
    }

    async function clearServerDataForCurrentChat(chatKey) {
        const errors=[];
        try{await serverFetch(`/indexes/${encodeURIComponent(chatKey)}`,{method:'DELETE'});}catch(error){errors.push(`索引：${error.message}`);}
        try{await serverFetch(`/tasks?chatKey=${encodeURIComponent(chatKey)}`,{method:'DELETE'});}catch(error){errors.push(`任务：${error.message}`);}
        return errors;
    }

    async function wipeCurrentTheaterData({unhide=true,silent=false}={}) {
        const scope=captureChatScope();const operationState=stateRuntime.state;const startCtx=context();
        if(!scope||!operationState)throw new Error('Cuộc trò chuyện hiện tại chưa nạp xong, hãy xóa sau');
        const preservedSettings=clone(operationState.settings||defaultState().settings);
        // 极稳模式：真正Bỏ chọn前固定留一份“pre-wipe”保险快照。它不参与当前数据，也不会被chính vănAI读取；只用于误删恢复。
        await createSafetySnapshot('pre-wipe-safety-vault',{force:true,stateSnapshot:clone(operationState),scope});
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==operationState)throw new Error('Đã đổi cuộc trò chuyện giữa chừng khi xóa, thao tác đã dừng an toàn; ảnh chụp bảo hiểm của cuộc cũ vẫn được giữ');
        resetTransientRuntimeForWipe(scope);
        if(!await clearTheaterMessageExtras(scope))throw new Error('Cuộc trò chuyện thay đổi giữa chừng khi xóa, đã ngừng ghi tiếp');
        if(unhide&&!await unhideEntireCurrentChat(scope))throw new Error('Cuộc trò chuyện thay đổi trong lúc khôi phục các tầng bị ẩn, đã ngừng ghi tiếp');
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==operationState)throw new Error('Đã đổi cuộc trò chuyện giữa chừng khi xóa, đã ngừng ghi tiếp');
        const serverErrors=await clearServerDataForCurrentChat(scope.serverChatKey);
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==operationState)throw new Error('Đã đổi cuộc trò chuyện trong lúc xóa chỉ mục trên máy chủ; cuộc trò chuyện hiện tại không bị sửa');
        try{localStorage.removeItem(scope.localStorageKey);}catch{}
        if(startCtx?.chatMetadata&&getChatKey(startCtx)===scope.chatKey&&Object.prototype.hasOwnProperty.call(startCtx.chatMetadata,META_KEY))delete startCtx.chatMetadata[META_KEY];
        const next=defaultState();next.settings={...next.settings,...preservedSettings};next.chatIdentity=scope.chatKey;next.chatAnchor=scope.chatAnchor;next.intentionalResetAt=Date.now();next.progress.maxObservedFloor=(startCtx?.chat?.length||0)-1;
        stateRuntime.state=next;stateRuntime.takeoverAbort=false;
        await withDestructiveSave(()=>saveState({immediate:true,refresh:false,reason:'wipe-reset',allowDestructive:true,forceSnapshot:true}));
        if(!chatScopeIsCurrent(scope)||stateRuntime.state!==next)return {serverErrors,switched:true};
        updatePromptInjection();applyUiCollapse();
        if(!silent){toast(serverErrors.length?`本聊天已Bỏ chọn；${serverErrors.join('; ')}（Bỏ chọn前安全快照仍可恢复）`:'Dữ liệu hoạt động vvv Sân Khấu Nhỏ của cuộc trò chuyện này đã được xóa; ảnh chụp an toàn trước khi xóa đã lưu vào hầm bảo hiểm',serverErrors.length?'warn':'success');renderCurrentTab();}
        return {serverErrors,switched:false};
    }

    function renderSettings() {
        const s=stateRuntime.state.settings;
        const toggle=(key,label,description)=>{
            if(key==='syncWorldBooksAcrossClients')return '';
            if(key==='autoCompanionOutput')description='每轮可见chính văn结束后，用幕后七条独立API读取本轮chính văn、有限记忆、已确认角色资料，以及“强读世界书”显式摘录（开启时）；不读取酒馆预设、Persona或Prompt Manager。chính văn和幕后始终分开输出。';
            if(key==='phoneAutoGenerate')description='每轮由幕后七条根据当前chính văn、当前场景、有限记忆与强读世界书摘录重新判断通讯方式；现代场景固定iPhone17Promax，其他时代按当前地点选择合理载体。';
            if(key==='autoEcologyRepair')return `<label class="vvvtm-setting"><div><strong>Tự bổ sung mục còn thiếu (luôn bật)</strong><small>Nếu kết quả chính bỏ sót ngoại hình nhân vật, Khoảnh khắc/nhật ký, thiết bị liên lạc hay Bỉ Gian Tư Văn thì chỉ bù đúng mục thiếu rồi nghiệm thu lại; không viết lại chính văn hay lặp lại những mục đã sinh ra.</small></div><input type="checkbox" checked disabled></label>`;
            return `<label class="vvvtm-setting"><div><strong>${label}</strong><small>${description}</small></div><input type="checkbox" data-setting="${key}" ${s[key]?'checked':''}></label>`;
        };
        const number=(key,label,min,max,step=1)=>{if(key==='companionRetryMaxAttempts')max=8;return `<label class="vvvtm-setting"><div><strong>${label}</strong></div><input type="number" min="${min}" max="${max}" step="${step}" data-setting-number="${key}" value="${esc(s[key])}"></label>`;};
        return `<section class="vvvtm-settings-columns"><article class="vvvtm-card"><h3>🧠 Luồng ký ức</h3><label class="vvvtm-setting"><div><strong>Nguồn AI cho ký ức và tổng kết</strong><small>Việc sắp xếp, tổng kết giai đoạn, tổng kết lớn và tổng kết thời đại luôn dùng API riêng với tư liệu có hạn; không đọc preset của SillyTavern, sách thế giới hay Persona, cũng không chuyển sang API chính của SillyTavern.</small></div><select data-setting-select="aiMode" disabled><option value="server" selected>API riêng · ranh giới tư liệu riêng</option></select></label>${toggle('autoExtract','Ghi nhanh tức thời · mỗi lượt trả lời AI một lần','Khi chơi bình thường, cứ mỗi lượt trả lời của AI/nhân vật hoàn tất là chạy ký ức chính một lần; tin của user chỉ làm ngữ cảnh, tuyệt đối không tự kích hoạt và cũng không tạo dòng thời gian cho user.')}<div class="vvvtm-note">Chiến lược cố định: 1 lượt trả lời của AI = 1 lần chạy luồng ký ức; kết quả sắp xếp chỉ ghi vào ký ức chạy nền, không sinh thêm lượt trả lời thứ hai trong khung chat.</div>${toggle('detailRescueEnabled','Phương án đáy cho chi tiết đời sống bị sót','主记忆负责anchors/lifeFacts；本地健康检查发现明确漏项后，在settled之后自动补抓。幕后七条成功与否都不会阻止补漏。')}${number('detailRescueMaxCandidates','每轮生活细节保底上限',4,24)}${number('detailRescueTimeoutMs','后台补抓超时（毫秒）',10000,60000,1000)}${number('detailRescueMaxAttempts','P13自动补抓最大尝试',1,5)}${number('detailRescueRetryBaseMs','P13重试基础等待（毫秒）',250,10000,250)}${number('lifeFactStabilityEvidence','习惯沉淀证据次数',2,8)}${toggle('autoSummary','自动阶段总结','按固定Tầng边界总结，失败不会跳过。')}${toggle('autoHideSummarized','总结成功后自动 /hide','阶段总结完成后自动执行 /hide 开始Tầng-结束Tầng；原消息仍可见，但不再进入AI提示词。')}${number('memoryCollectionMaxChars','记忆集合单次原文安全容量（字符）',12000,240000,1000)}${number('summaryEvery','每次阶段总结Tầng',5,200)}${number('stageSummariesPerBig','每几次阶段总结合并大总结',2,20)}${number('bigSummariesPerEra','每几次大总结合并时代总结',2,50)}${toggle('parseMemoryTags','读取 <Memory> JSON标签','回复中自带结构化记忆时直接导入。')}</article>
        <article class="vvvtm-card"><h3>🔎 Truy hồi và nạp vào</h3>${toggle('ultraLongArchiveMode','Chế độ hồ sơ dài hạn 20.000 tầng','Bật ba cấp tổng kết, ký ức nóng - nguội và phân trang danh sách siêu dài; sẽ không nhồi toàn bộ cuộc trò chuyện cũ cho AI viết chính văn.')}${toggle('injectMemory','Nạp ký ức','Gửi nhân vật/quan hệ hiện tại, sự kiện cốt lõi cả đời, ba cấp tổng kết, cùng những chi tiết cũ chính xác được gọi lại từ kho nguội theo cốt truyện hiện tại.')}${toggle('strongWorldBookRead','Đọc cưỡng bức sách thế giới (khuyến nghị)','每次正常角色回复前，额外读取当前角色主世界书、角色附加世界书、聊天世界书与已启用全局世界书；常驻/命中条目优先，其余绑定条目按预算补读。不修改世界书本身。')}${number('strongWorldBookMaxChars','强读世界书最大字符',2000,30000,1000)}${toggle('protectSceneContinuity','当前现实/场景防回滚锁（强烈推荐）','最新user的地点、姿势、衣着、物品与Đã hoàn thành动作拥有最高优先级；旧scene/旧记忆不得把剧情拉回已经离开的地点。')}${toggle('protectUserAgency','USER主权锁（强烈推荐）','正常角色chính văn只允许AI控制char/NPC/环境；禁止替user新增对白、动作、决定、心理和主动身体反应。Tiếp sức cốt truyện bằng AI代写user时不受此开关限制。')}${number('maxInjectChars','每轮最大记忆注入字符',1000,30000)}${number('hotMemoryFloors','热记忆窗口（最近Tầng）',50,3000)}${toggle('retrievalEnabled','启用混合检索','Dòng thời gian、总结、Quan hệ nhân vật、电话/微信/朋友圈/日记/纪念日都可检索；向量未配置时用BM25。')}${toggle('vcpMemoryEnabled','VCP式联想记忆（推荐）','不复制VCP源码；服务器会把人物、事件、物品、地点、关系、Lời hẹn、秘密、通讯与生活痕迹构成标签关联图，再做跨Loại联想与核心记忆重排。')}${number('vcpTagWeight','直接标签权重',0,.5,.01)}${number('vcpGraphWeight','跨记忆联想权重',0,.5,.01)}${number('vcpCoreWeight','核心记忆引力',0,.3,.01)}${number('vcpMaxExpandedTags','每轮最多联想标签',2,24,1)}${toggle('autoReindex','记忆变化后自动重建索引','正常聊天自动异步重建；大型后台任务由独立统一队列调度。')}${number('retrievalTopK','召回数量',1,30)}${number('retrievalMinScore','最低相关度',0,1,.01)}${number('vectorWeight','向量权重',0,1,.05)}${number('lexicalWeight','关键词权重',0,1,.05)}</article>
        <article class="vvvtm-card"><h3>🙈 Thu gọn và nén ngữ cảnh</h3>${toggle('uiCollapseSummarized','Giao diện thu gọn các tầng đã tổng kết','Chỉ ảnh hưởng phần trò chuyện bạn nhìn thấy, không ảnh hưởng tới AI.')}${toggle('compressSummarizedContext','Nén ngữ cảnh các tầng đã tổng kết','AI không còn nhận chính văn cũ nữa, thay vào đó gửi bản tổng kết và ký ức truy hồi được.')}${number('preserveFirst','Luôn giữ các tầng mở đầu',0,30)}${number('keepLast','Luôn giữ các tầng gần nhất',5,300)}${toggle('preserveImportant','Giữ lại các tầng quan trọng đã đánh dấu thủ công','Tin nhắn quan trọng sẽ không bị thu gọn hay nén.')}${toggle('keepRetrievedFloors','Giữ lại các tầng mà truy hồi lượt này khớp trúng','Để AI đọc được chi tiết gốc.')}<div class="vvvtm-row-actions"><button data-setting-action="expand-ui">Tạm mở tất cả</button><button data-setting-action="mark-current">Đánh dấu tầng hiện tại là quan trọng</button></div></article>
        <article class="vvvtm-card"><h3>🎨 Giao diện và hỗ trợ</h3>${number('uiPageSize','Số mục mỗi trang của danh sách siêu dài',10,100,5)}${toggle('hideCompletedSummaryCards','Trung tâm tổng kết ẩn các thẻ đã hoàn thành','Dữ liệu vẫn được giữ.')}${toggle('autoCompanionOutput','Bảy điều hậu trường viết ở nền (khuyến nghị)','每轮可见chính văn完成后，由幕后七条专用独立API单独调用1次，一次性生成当前场景、Lời hẹn/秘密、人物外观、朋友圈/日记/纪念日、通讯终端和彼间私文；模型可在“API与模型”单独选择。')}${toggle('autoEcologyRepair','手机/彼间私文二次补活（可选，额外1次）','幕后七条本身已经读取静默债务并负责活化。仅在你主动开启本开关且七条结果仍死寂时，再额外调用1次同一个幕后七条写作源；默认Đóng以固定每轮只用1次后台请求。')}${number('companionRetryMaxAttempts','幕后七条失败最多自动重试次数',1,5,1)}${toggle('companionSkipGreeting','开场白保护','新卡开场白、替换开场白和仅加载聊天时不读取、不生成通讯与彼间私文。')}${toggle('phoneAutoGenerate','AI自主判断通讯方式与联系内容','每轮读取当前场景+角色卡+世界书重新判断：现代场景固定iPhone17Promax（断网/无信号只标记不可用）；其他时代/区域由AI按当前地点自由选择具体通讯载体。')}${toggle('phoneEcologyEnabled','手机生态增强','让联系人、群聊/频道、时代通讯噪声和实时联络像真实社会一样在后台生活；user不打开终端也会积累NPC↔NPC互动。')}${toggle('phoneInstitutionBootstrap','按人设自动建立稳定社交群','P26把原世界Thân phận与当前时空拆开：原班级/朋友群跨世界时保留但离线；若剧情在异世界/历史时代加入当地学校或组织，则建立当地传讯频道/电报簿/联络簿，不会硬塞微信。')}${number('phoneGroupActivity','群聊/频道后台活跃度（0-1）',0,1,.05)}${number('phoneServiceNoise','通讯环境噪声（0-1）',0,1,.05)}${number('phoneDeadAirMaxFloors','手机最多连续静默Tầng',1,12,1)}${number('phoneDirectContactMaxFloors','NPC最多几层不直接找user',2,20,1)}${number('phonePrivateMaxMessages','每轮私聊最多条数',1,8,1)}${number('phoneGroupMaxMessages','每轮群聊最多条数',1,12,1)}${number('phoneSmsMaxMessages','每轮短信最多条数',1,8,1)}${number('phoneCallMaxEvents','每轮电话最多事件',1,4,1)}${toggle('npcCallVariety','NPC来电自然度增强','避免NPC长期只发文字：连续多次NPC文字联系后，遇到合理即时沟通动机会优先考虑真实来电，但不会每轮强制打电话。')}${number('npcCallEscalationAfter','连续几次NPC文字联系后加强来电倾向',2,12)}${toggle('autoCharacterWorld','推进彼间私文','由每轮幕后七条后台写作持续映射全部NPC的独立生活；NPC可主动联系/打断user。')}${toggle('npcWorldAutonomy','NPC大世界自治增强','NPC彼此之间也会生活、交友、恋爱、争吵、工作、搬家、失联或改变目标；不是所有事件都围绕user。')}${number('npcWorldSpontaneity','NPC世界自发度（0-1）',0,1,.05)}${number('worldDeadAirMaxFloors','彼间私文最多连续静默Tầng',1,12,1)}${number('worldMinPulseEvents','触发世界心跳时最低NPC动态数',1,8,1)}${number('companionWorldMaxEvents','彼间私文最低并行槽位（会自动扩展覆盖全部NPC）',1,80)}<label class="vvvtm-setting"><div><strong>Cách trả lời liên lạc</strong><small>Chế độ khuyến nghị sẽ chờ chính văn lượt sau kết thúc rồi trả lời luôn trong cùng một yêu cầu chạy nền của Bảy điều hậu trường, không thêm một yêu cầu nữa.</small></div><select data-setting-select="phoneInteractiveMode"><option value="next-main" ${s.phoneInteractiveMode!=='plugin-immediate'?'selected':''}>Gộp trả lời vào Bảy điều hậu trường lượt sau (khuyến nghị)</option><option value="plugin-immediate" ${s.phoneInteractiveMode==='plugin-immediate'?'selected':''}>Bảy điều hậu trường trả lời ngay (thêm một lượt)</option></select></label>${toggle('removeDuplicateAssistantReplies','自动清理完全重复的相邻AITầng','Chỉ xử lý hai tầng cùng nhân vật, liền kề, cách nhau dưới năm phút và có chính văn hoàn toàn giống nhau.')}${toggle('companionAlwaysShowShell','每轮显示通讯与彼间私文入口','Kể cả khi bảy điều lượt này không có nội dung mới hoặc nguồn viết không dùng được thì vẫn hiện trạng thái, tránh hiểu nhầm là tiện ích không chạy.')}${toggle('syncWorldBooksAcrossClients','跨端世界书刷新保护','每次打开/切换聊天时重新读取酒馆实际启用的角色/聊天/全局世界书，减少手机和电脑显示/读取Trạng thái不同步。')}${toggle('diagnosticsUseAI','剧情体检使用AI','本地规则始终可用。')}</article></section>
        <section class="vvvtm-card"><div class="vvvtm-section-title"><div><h3>🛡️ Bảo vệ dữ liệu cực ổn định</h3><p class="vvvtm-note">Máy chủ liên tục lưu trọn trạng thái 0-32 của cuộc trò chuyện hiện tại, ảnh chụp lịch sử giữ vĩnh viễn và không tự cắt bớt; mở/đổi cuộc trò chuyện không thực hiện cắt bỏ có tính phá hủy; khi phát hiện số lượng ký ức sụt giảm bất thường thì từ chối ghi đè.</p></div></div>${toggle('safetySnapshots','Ảnh chụp an toàn trạng thái đầy đủ trên máy chủ','Nên bật vĩnh viễn. Khi metadata bất thường, localStorage của trình duyệt vượt hạn mức hoặc bị xóa nhầm thì vẫn khôi phục được.')}${number('safetySnapshotIntervalSeconds','Khoảng cách tối thiểu giữa hai ảnh chụp tự động (giây)',15,600,5)}<div class="vvvtm-action-grid"><button data-setting-action="snapshot-now">📸 Chụp ảnh an toàn ngay</button><button data-setting-action="restore-latest">♻️ Khôi phục ảnh chụp an toàn gần nhất</button><button data-setting-action="restore-history">🗂 Chọn ảnh chụp lịch sử để khôi phục</button></div></section><section class="vvvtm-card"><div class="vvvtm-section-title"><div><h3>🗑 Dữ liệu đã xóa / thùng rác</h3><p class="vvvtm-note">U1.4: dữ liệu có cấu trúc do chính bạn xóa sẽ vào thùng rác bia mộ trước; ở đây khôi phục lại được. Nâng cấp thường, đồng bộ hay việc xóa chính văn không tạo bia mộ và cũng không có quyền xóa.</p></div></div>${recycleBinMarkup()}</section><section class="vvvtm-card vvvtm-danger-zone"><div class="vvvtm-section-title"><div><h3>Dữ liệu, an toàn và khôi phục</h3><p class="vvvtm-note">“Xóa sạch một chạm” sẽ xóa dữ liệu đang hoạt động và khôi phục /hide; chế độ cực ổn định sẽ giữ thêm một ảnh chụp bảo hiểm trước khi xóa, không tham gia việc AI đọc và có thể khôi phục khi lỡ tay. Cuộc trò chuyện thật, thẻ nhân vật, sách thế giới, bản thân tiện ích và cấu hình API riêng sẽ không bị xóa.</p></div></div><div class="vvvtm-action-grid"><button data-setting-action="migrate">Di trú Memory-Context cũ</button><button data-setting-action="import">Nhập bản sao lưu</button><button data-setting-action="export">Xuất bản sao lưu</button><button data-setting-action="rebuild">Dựng lại chỉ mục truy hồi</button><button data-setting-action="reset-progress">Tính lại các chỗ hổng của tổng kết</button><button data-setting-action="clear-tasks">Dọn bản ghi tác vụ đã hoàn thành</button><button data-setting-action="wipe-all" class="danger-soft">🗑 Xóa một chạm dữ liệu hoạt động của cuộc trò chuyện này</button></div><input id="vvvtm-import-file" type="file" accept="application/json,.json" hidden></section>`;
    }

    function bindSettings(content) {
        content.querySelector('[data-setting-select="phoneInteractiveMode"]')?.closest('.vvvtm-setting')?.remove();
        content.querySelectorAll('[data-setting]').forEach(input=>input.addEventListener('change',()=>{stateRuntime.state.settings[input.dataset.setting]=input.checked;stateRuntime.uiExpanded=false;applyButtonVisibility();saveState({refresh:true});applyUiCollapse();}));
        content.querySelectorAll('[data-setting-number]').forEach(input=>input.addEventListener('change',()=>{const key=input.dataset.settingNumber;const next=Number(input.value);if(key==='summaryEvery'&&next!==Number(stateRuntime.state.settings.summaryEvery||20)&&completedSummaryRows('Tổng kết giai đoạn').length){input.value=stateRuntime.state.settings.summaryEvery;toast('Khi đã có tổng kết giai đoạn thì không được đổi thẳng độ dài phân đoạn, nếu không chuỗi tổng kết sẽ chồng lấn hoặc đứt gãy. Hãy giữ nguyên độ dài hiện tại, hoặc xóa sạch một cách rõ ràng rồi dựng lại.','warn');return;}stateRuntime.state.settings[key]=next;if(key==='summaryEvery')recalculateSummaryProgress();saveState();}));
        content.querySelectorAll('[data-setting-select]').forEach(input=>input.addEventListener('change',()=>{stateRuntime.state.settings[input.dataset.settingSelect]=input.value;saveState();}));
        content.querySelector('[data-setting-action="migrate"]')?.addEventListener('click',manualMigrate);
        content.querySelector('[data-setting-action="export"]')?.addEventListener('click',exportData);
        content.querySelector('[data-setting-action="import"]')?.addEventListener('click',()=>content.querySelector('#vvvtm-import-file')?.click());
        content.querySelector('#vvvtm-import-file')?.addEventListener('change',importData);
        content.querySelector('[data-setting-action="rebuild"]')?.addEventListener('click',()=>rebuildIndex());
        content.querySelector('[data-setting-action="expand-ui"]')?.addEventListener('click',()=>{stateRuntime.uiExpanded=true;applyUiCollapse();toast('Trang này đã mở rộng; sau khi tải lại sẽ thu gọn theo cài đặt','success');});
        content.querySelector('[data-setting-action="mark-current"]')?.addEventListener('click',()=>{const floor=Math.max(0,(context()?.chat?.length||1)-1);if(!stateRuntime.state.importantFloors.includes(floor))stateRuntime.state.importantFloors.push(floor);saveState({refresh:true});scheduleReindex();toast(`已标记第 ${floor} 层重要`,'success');});
        content.querySelector('[data-setting-action="snapshot-now"]')?.addEventListener('click',async()=>{setBusy(true,'Đang lưu ảnh chụp an toàn đầy đủ…');try{const snap=await createSafetySnapshot('manual-snapshot',{force:true});toast(snap?'Đã lưu ảnh chụp an toàn':'Ảnh chụp chưa được lưu (hãy kiểm tra plugin phía máy chủ đã cập nhật chưa)',snap?'success':'warn');}finally{setBusy(false);}});
        content.querySelector('[data-setting-action="restore-latest"]')?.addEventListener('click',async()=>{if(!confirm('Khôi phục ảnh chụp an toàn gần nhất trên máy chủ sẽ ghi đè dữ liệu hoạt động hiện tại của vvv Sân Khấu Nhỏ, nhưng không sửa cuộc trò chuyện thật. Trước khi khôi phục, trạng thái hiện tại cũng được chụp lại một bản. Tiếp tục chứ?'))return;setBusy(true,'Đang khôi phục ảnh chụp an toàn gần nhất…');try{await createSafetySnapshot('before-manual-restore',{force:true});await restoreLatestSafetySnapshot();}catch(error){toast(`恢复失败：${error.message}`,'error');}finally{setBusy(false);}});
        content.querySelector('[data-setting-action="restore-history"]')?.addEventListener('click',async()=>{setBusy(true,'Đang đọc lịch sử ảnh chụp an toàn…');try{await chooseSafetySnapshotHistory();}catch(error){toast(`恢复失败：${error.message}`,'error');}finally{setBusy(false);}});
        content.querySelector('[data-setting-action="reset-progress"]')?.addEventListener('click',()=>{recalculateSummaryProgress();saveState({refresh:true,reason:'recalculate-summary-progress'});toast('Đã tính lại các chỗ hổng theo tổng kết giai đoạn hiện có, sẽ không tạo lại những giai đoạn đã có','success');});
        content.querySelector('[data-setting-action="clear-tasks"]')?.addEventListener('click',()=>{stateRuntime.state.summaryJobs=stateRuntime.state.summaryJobs.filter(job=>!job.applied&&!['error','completed'].includes(job.status));saveState({refresh:true});});
        content.querySelectorAll('[data-recycle-restore]').forEach(button=>button.addEventListener('click',async()=>{
            const row=(stateRuntime.state?.manualDeletionTombstones||[]).find(x=>x?.id===button.dataset.recycleRestore);if(!row)return;
            if(!confirm(`恢复 ${row.path} 中的 ${row.items?.length||0} 项已删除资料？`))return;
            setBusy(true,'Đang khôi phục dữ liệu từ thùng rác…');try{await createSafetySnapshot('before-recycle-restore',{force:true});const count=await restoreManualDeletionTombstone(row.id);toast(`已从回收站恢复 ${count} 项资料`,'success');}catch(error){toast(`恢复失败：${error.message}`,'error');}finally{setBusy(false);}
        }));
        content.querySelector('[data-setting-action="wipe-all"]')?.addEventListener('click',async()=>{if(!confirm(`确认一键彻底Bỏ chọn当前聊天的全部vvv小剧场数据吗？\n\n会同时Bỏ chọn记忆、总结、Dòng thời gian、人物/关系、手机、彼间私文、章节、检索索引、任务记录，并恢复被 /hide 的聊天Tầng。\n\n真实聊天、角色卡、世界书、插件本体和API配置不会删除。`))return;setBusy(true,'Đang xóa sạch cuộc trò chuyện này…');try{await wipeCurrentTheaterData({unhide:true,silent:false});}finally{setBusy(false);}});
    }

    function renderCurrentTab() {
        const content=document.getElementById('vvvtm-content');if(!content||!stateRuntime.state)return;
        if(stateRuntime.currentTab!=='phone') undockRolePhoneFromTab({hide:true});
        const renderers={overview:renderOverview,tables:renderTables,timeline:renderTimeline,characters:renderCharacters,relations:renderRelations,secrets:renderSecrets,summary:renderSummaryCenter,retrieval:renderRetrieval,phone:renderPhone,worldlife:renderCharacterWorld,appearance:renderAppearance,chapters:renderChapters,diagnostics:renderDiagnostics,api:renderApi,settings:renderSettings};
        content.innerHTML=renderers[stateRuntime.currentTab]?.()??renderOverview();
        content.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>jumpToFloor(button.dataset.jump)));
        bindPaging(content);
        if(stateRuntime.currentTab==='overview')bindOverview(content);if(stateRuntime.currentTab==='tables')bindTables(content);if(stateRuntime.currentTab==='secrets')bindSecrets(content);if(stateRuntime.currentTab==='summary')bindSummaryCenter(content);if(stateRuntime.currentTab==='retrieval')bindRetrieval(content);if(stateRuntime.currentTab==='phone')bindPhone(content);if(stateRuntime.currentTab==='worldlife')bindCharacterWorld(content);if(stateRuntime.currentTab==='appearance')bindAppearance(content);if(stateRuntime.currentTab==='chapters')bindChapters(content);if(stateRuntime.currentTab==='diagnostics')bindDiagnostics(content);if(stateRuntime.currentTab==='api')bindApi(content);if(stateRuntime.currentTab==='settings')bindSettings(content);
        globalThis.dispatchEvent?.(new CustomEvent('vvvtm-content-rendered',{detail:{tab:stateRuntime.currentTab}}));
    }

    function clearTransientTimer(field) {
        const timer=stateRuntime[field];
        if(timer)clearTimeout(timer);
        stateRuntime[field]=null;
    }

