        stateRuntime.fallbackProgressTimers.clear();
        stateRuntime.fallbackProgressValues.clear();
        stateRuntime.lifeRescueInFlight.clear();
        stateRuntime.lifeRescueResumeRunning=false;stateRuntime.lifeRescueResumeToken=null;
        stateRuntime.incomingCallShown.clear();
        stateRuntime.extractRetryAttempt=0;
        stateRuntime.extracting=false;stateRuntime.extractOperationToken=null;stateRuntime.memoryPipelineNotice='';
        stateRuntime.recentEventRerunFloor=-1;
        stateRuntime.summaryRunning=false;stateRuntime.summaryOperationToken=null;
        stateRuntime.memoryCollectionAbort=true;stateRuntime.memoryCollectionRunning=false;stateRuntime.memoryCollectionOperationToken=null;
        stateRuntime.memoryReviewAbort=true;stateRuntime.memoryReviewRunning=false;stateRuntime.memoryReviewOperationToken=null;stateRuntime.memoryReviewResult=null;stateRuntime.memoryReviewReportClosed=true;
        stateRuntime.companionRunning=false;stateRuntime.companionOperationToken=null;
        stateRuntime.mainCompanionProcessing=false;stateRuntime.mainCompanionToken=null;
        stateRuntime.duplicateGuardRunning=false;stateRuntime.duplicateGuardToken=null;
        stateRuntime.worldBookSyncing=false;stateRuntime.worldBookSyncToken=null;
        stateRuntime.phoneServerRecoveryToken=null;
        stateRuntime.phoneSending=false;stateRuntime.phoneSendingToken=null;
        stateRuntime.phoneDialog=null;stateRuntime.phonePaymentDigits='';stateRuntime.phoneDraftAttachment=null;
        stateRuntime.phoneStickerPanel=false;stateRuntime.phoneStickerManage=false;stateRuntime.phoneStickerQuery='';stateRuntime.phoneStickers=[];stateRuntime.phoneStickersLoaded=false;stateRuntime.phoneStickersLoading=false;stateRuntime.phoneStickerLoadError='';stateRuntime.phoneStickerLoadPromise=null;stateRuntime.phoneActiveCallId='';stateRuntime.phoneTavernCharacterId='';stateRuntime.phoneTavernSessionId='';
        stateRuntime.phoneMomentDraftAttachments=[];stateRuntime.phoneMomentDraftContent='';
