        stateRuntime.generationActive=false;
        stateRuntime.backgroundGenerationActive=false;
        stateRuntime.liveUserPending=false;
        stateRuntime.liveUserFloor=-1;
        stateRuntime.liveTurnChatKey='';
        stateRuntime.liveGenerationType='';
