    globalThis.vvvTheaterMemoryInterceptor = async function vvvTheaterMemoryInterceptor(chat, _contextSize, _abort, type) {
        try {
            if (!Array.isArray(chat)) return;
            const s = stateRuntime.state;
            const generationType = String(type || 'normal').toLowerCase();
            const isMainAssistantReply = !['quiet','impersonate'].includes(generationType);
            if(isMainAssistantReply&&s?.settings?.enabled&&s.settings.retrievalEnabled)await prepareRetrievalForGeneration(chat,700);

            // 原有上下文压缩：仅在启用时执行。P27主AI导演不依赖压缩开关。
            if (s?.settings?.enabled && s.settings.compressSummarizedContext) {
                const maxFloor=maxSummarizedFloor();
                if(maxFloor>=0){
                    const preserve=Math.max(0,Number(s.settings.preserveFirst||0));const keepLast=Math.max(5,Number(s.settings.keepLast||30));const recentStart=Math.max(preserve,chat.length-keepLast);
                    const protectedFloors=new Set((s.importantFloors||[]).map(Number));if(s.settings.keepRetrievedFloors)stateRuntime.retrievalHits.forEach(hit=>{const a=Number(hit.floorStart),b=Number(hit.floorEnd??a);if(Number.isFinite(a))for(let i=a;i<=Math.min(b,a+50);i+=1)protectedFloors.add(i);});
                    const kept=[];for(let i=0;i<Math.min(preserve,chat.length);i+=1)kept.push(chat[i]);
                    const middleProtected=[];for(let i=preserve;i<recentStart;i+=1){if(!floorCoveredByCompletedStage(i)||protectedFloors.has(i))middleProtected.push(i);}
                    const summaries=[...completedSummaryRows('Tổng kết lớn').slice(-2),...completedSummaryRows('Tổng kết giai đoạn').slice(-5)].map(row=>`【${row['Loại']||row['Loại bảng']} ${row['Tầng bao phủ']}层】${row['Nội dung tổng kết']}`).join('\n\n');
                    const safeRetrievalHits=(stateRuntime.retrievalHits||[]).map(h=>sanitizeRetrievalDocumentText(h?.text)).filter(Boolean);
                    kept.push({name:'Trung tâm Ký ức vvv',is_user:false,is_system:true,mes:`[已总结旧Tầng的压缩记忆]\n${summaries}\n\n${safeRetrievalHits.length?`[本轮相关旧记忆]\n${safeRetrievalHits.map(text=>`- ${text}`).join('\n')}`:''}`.slice(0,Number(s.settings.maxInjectChars||8000)),send_date:Date.now()});
                    middleProtected.forEach(i=>{if(chat[i])kept.push(chat[i]);});for(let i=recentStart;i<chat.length;i+=1)if(chat[i])kept.push(chat[i]);
                    chat.splice(0,chat.length,...kept);
                }
            }

            if(isMainAssistantReply&&s?.settings?.enabled&&s.settings.retrievalEnabled){
                const retrievalNote=generationRetrievalNote(chat);
                if(retrievalNote)chat.splice(chat.length>0?Math.max(0,chat.length-1):0,0,retrievalNote);
            }

            // R21 fixed7：强读仅限当前实际绑定的世界书。SillyTavern原生关键词激活仍保留，
            // 这里是在正常角色回复前额外提供一份有界、高优先级的绑定世界书摘录。
            if(isMainAssistantReply&&s?.settings?.enabled&&s.settings.strongWorldBookRead!==false){
                const worldBookDigest=await buildStrongWorldBookDigest();
                if(worldBookDigest){
                    const insertAt=chat.length>0?Math.max(0,chat.length-1):0;
                    chat.splice(insertAt,0,systemNoteForGeneration(chat,worldBookDigest,'0-32 đọc cưỡng bức sách thế giới'));
                }
            }

            // P27：官方生成拦截器会给出 generation type。
            // 只给正常角色回复类生成注入导演；quiet / impersonate 明确跳过，避免污染0-32 user接力或酒馆“代写user”。
            if (isMainAssistantReply && mainDirectorEnabledFromRelay()) {
                const director = mainAiDirectorInstruction(chat);
                if (director) {
                    const note = { name:'Đạo diễn cốt truyện 0-32', is_user:false, is_system:true, mes:director, send_date:Date.now() };
                    // 按官方拦截器推荐思路放在“最后一条待生成上下文”之前：
                    // normal通常在最新user之前；continue则在待续写assistant之前，同样靠近本轮生成末端。
                    const insertAt = chat.length > 0 ? Math.max(0, chat.length - 1) : 0;
                    chat.splice(insertAt,0,note);
                }
            }

            // P35：正式主AI最后一拍边界。兼容 SillyTavern 两种 generate_interceptor 消息结构：
            // 旧式 {is_user,is_system,mes} 与 OpenAI式 {role,content}。P34只识别前者，
            // 某些生成链上会找不到最新user，导致这条锁实际没有进入模型上下文。
            if (isMainAssistantReply && s?.settings?.enabled && s.settings.protectUserAgency !== false) {
                const isSystemMsg = (m) => Boolean(m?.is_system) || String(m?.role || '').toLowerCase() === 'system';
                const isUserMsg = (m) => !isSystemMsg(m) && (m?.is_user === true || String(m?.role || '').toLowerCase() === 'user');
                const latestUserIndex = (() => {
                    for (let i=chat.length-1;i>=0;i-=1) if (isUserMsg(chat[i])) return i;
                    return -1;
                })();
                const antiReplay = latestUserNoReplayInstruction();
                if (latestUserIndex >= 0 && antiReplay) {
                    const sample = chat[latestUserIndex] || {};
                    const openAiShape = Object.prototype.hasOwnProperty.call(sample,'role') || Object.prototype.hasOwnProperty.call(sample,'content');
                    const note = openAiShape
                        ? { role:'system', content:antiReplay }
                        : { name:'Ranh giới tiếp nối lượt này của 0-32', is_user:false, is_system:true, mes:antiReplay, send_date:Date.now() };
                    chat.splice(latestUserIndex + 1, 0, note);
                }
            }
        } catch(error) {
            console.warn('[vvv Trung tâm Ký ức] Bộ chặn lượt sinh xử lý thất bại, lượt này giữ nguyên cuộc trò chuyện gốc', error);
        }
    };


